    scene.add(rooftop2);

    var vendorWreck = createStreetVendorWreck(-12, 0, 5);
    scene.add(vendorWreck);

    var tank1 = createRainCatchmentTank(8, 0, 8);
    scene.add(tank1.tank);
    scene.add(tank1.cap);

    var tank2 = createRainCatchmentTank(10, 0, 10);
