      var barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, 12, 12), barrelMat);
      barrel.rotation.x = Math.PI / 6;
      barrel.position.set(100 + (i === 0 ? -2 : 2), 4, 50);
