		var barrelGeometry = new THREE.CylinderGeometry(2, 2, 15, 8);
		var barrel = new THREE.Mesh(barrelGeometry, metalMaterial);
		barrel.position.set(-150, 55, -140);
		barrel.rotation.x = -0.3;
		barrel.castShadow = true;
