    var pulleyGroup = new THREE.Group();

    // Support beam
    var beamMat = new THREE.MeshPhongMaterial({ color: 0x333333, metalness: 0.7 });
    var beamGeom = new THREE.BoxGeometry(80, 6, 6);
    var beam = new THREE.Mesh(beamGeom, beamMat);
