    resortObjects.push(front);

    // Serving area
    var servGeom = new THREE.BoxGeometry(8, 1, 4);
    var serv = new THREE.Mesh(servGeom, materials.concrete);
    serv.position.copy(pos);
    serv.position.y = 1.5;
