try {
;
window.JungleRuin = (function() {
  'use strict';

  var scene, camera;
  var vineMeshes = [];
  var fireflyMeshes = [];
  var gemMeshes = [];
  var rootMeshes = [];
  var time = 0;

  function init(sceneParam, cameraParam) {
    scene = sceneParam;
    camera = cameraParam;

    // Lighting setup
    var ambientLight = new THREE.AmbientLight(0x4a7c59, 0.6);
    scene.add(ambientLight);

    var directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(20, 40, 20);
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    directionalLight.castShadow = true;
    scene.add(directionalLight);

    var hemisphereLight = new THREE.HemisphereLight(0x87ceeb, 0x2d5016, 0.5);
    scene.add(hemisphereLight);

    // Crumbling stone structures - ruins base
    buildRuinsBase();

    // Stepped pyramid structure
    buildPyramid();

    // Massive tree trunks with canopy
    buildTrees();

    // Tree roots breaking through walls
    buildTreeRoots();

    // Stone guardian statue
    buildGuardianStatue();

    // Hidden passage entrance
    buildHiddenPassage();

    // Overgrown courtyard
    buildCourtyard();

    // Underground treasure chamber
    buildTreasureChambel();

    // Jaguar silhouettes on branches
    buildJaguars();

    // Hanging vines (LineSegments)
    buildHangingVines();

    // Firefly/butterfly particles
    buildFireflies();

    // Fog for atmosphere
    scene.fog = new THREE.FogExp2(0x4a7c59, 0.08);
    scene.background = new THREE.Color(0x4a7c59);
  }

  function buildRuinsBase() {
    var ruinPositions = [
      { x: -15, y: 2, z: -10, w: 8, h: 4, d: 6 },
      { x: 10, y: 2, z: 5, w: 7, h: 5, d: 8 },
      { x: -5, y: 3, z: 15, w: 10, h: 6, d: 5 },
      { x: 18, y: 1.5, z: -15, w: 6, h: 3, d: 7 },
      { x: -20, y: 2, z: 8, w: 5, h: 4, d: 9 }
    ];

    var mossyColors = [0x6b8e6f, 0x7a9d7e, 0x5d7a60, 0x718c74, 0x658970];
    var colorIdx = 0;

    ruinPositions.forEach(function(pos) {
      var geometry = new THREE.BoxGeometry(pos.w, pos.h, pos.d);
      var material = new THREE.MeshStandardMaterial({
        color: mossyColors[colorIdx % mossyColors.length],
        roughness: 0.8,
        metalness: 0.1
      });
      var mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(pos.x, pos.y, pos.z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.rotation.x = (Math.random() - 0.5) * 0.3;
      mesh.rotation.z = (Math.random() - 0.5) * 0.2;
      scene.add(mesh);
      colorIdx++;
    });
  }

  function buildPyramid() {
    var baseSize = 20;
    var baseHeight = 1.5;
    var levels = 5;

    for (var i = 0; i < levels; i++) {
      var size = baseSize - (i * 3.5);
      if (size < 1) size = 1;

      var geometry = new THREE.BoxGeometry(size, baseHeight, size);
      var material = new THREE.MeshStandardMaterial({
        color: 0x8b8680,
        roughness: 0.9,
        metalness: 0
      });
      var mesh = new THREE.Mesh(geometry, material);
      mesh.position.y = i * baseHeight + 1;
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      // Partial collapse effect
      if (i > 2 && Math.random() > 0.5) {
        mesh.rotation.z = (Math.random() - 0.5) * 0.4;
      }

      scene.add(mesh);
    }

    // Collapsed section
    var collapseGeo = new THREE.BoxGeometry(8, 2, 4);
    var collapseMat = new THREE.MeshStandardMaterial({ color: 0x7a7569, roughness: 0.85 });
    var collapseMesh = new THREE.Mesh(collapseGeo, collapseMat);
    collapseMesh.position.set(-8, 5, 0);
    collapseMesh.rotation.z = 0.6;
    collapseMesh.castShadow = true;
    scene.add(collapseMesh);
  }

  function buildTrees() {
    var treePositions = [
      { x: 25, y: 0, z: -20, height: 35, canopyRadius: 12 },
      { x: -30, y: 0, z: 10, height: 38, canopyRadius: 14 },
      { x: 8, y: 0, z: 35, height: 30, canopyRadius: 10 },
      { x: -15, y: 0, z: -30, height: 33, canopyRadius: 11 }
    ];

    treePositions.forEach(function(pos) {
      // Tree trunk
      var trunkGeo = new THREE.CylinderGeometry(1.5, 2.5, pos.height, 8);
      var trunkMat = new THREE.MeshStandardMaterial({
        color: 0x3d2817,
        roughness: 0.9,
        metalness: 0
      });
      var trunkMesh = new THREE.Mesh(trunkGeo, trunkMat);
      trunkMesh.position.set(pos.x, pos.height / 2, pos.z);
      trunkMesh.castShadow = true;
      trunkMesh.receiveShadow = true;
      scene.add(trunkMesh);

      // Canopy clusters
      var clusterCount = 4;
      for (var i = 0; i < clusterCount; i++) {
        var angle = (i / clusterCount) * Math.PI * 2;
        var offsetX = Math.cos(angle) * (pos.canopyRadius * 0.7);
        var offsetZ = Math.sin(angle) * (pos.canopyRadius * 0.7);
        var offsetY = pos.height - 8 + Math.sin(angle * 2) * 3;

        var canopyGeo = new THREE.SphereGeometry(pos.canopyRadius * 0.8, 6, 6);
        var canopyMat = new THREE.MeshStandardMaterial({
          color: 0x2d5016,
          roughness: 0.7,
          metalness: 0
        });
        var canopyMesh = new THREE.Mesh(canopyGeo, canopyMat);
        canopyMesh.position.set(pos.x + offsetX, offsetY, pos.z + offsetZ);
        canopyMesh.castShadow = true;
        canopyMesh.receiveShadow = true;
        scene.add(canopyMesh);
      }
    });
  }

  function buildTreeRoots() {
    var rootSets = [
      { x: -10, y: 1, z: 5, rootX: 25, rootZ: -20 },
      { x: 5, y: 1, z: -8, rootX: -30, rootZ: 10 },
      { x: -18, y: 0.5, z: 18, rootX: 8, rootZ: 35 }
    ];

    rootSets.forEach(function(set) {
      var rootCount = 5;
      for (var i = 0; i < rootCount; i++) {
        var angle = (i / rootCount) * Math.PI * 2;
        var dirX = Math.cos(angle);
        var dirZ = Math.sin(angle);

        var rootGeo = new THREE.CylinderGeometry(0.8, 1.2, 6, 6);
        var rootMat = new THREE.MeshStandardMaterial({
          color: 0x5a4a3a,
          roughness: 0.8,
          metalness: 0
        });
        var rootMesh = new THREE.Mesh(rootGeo, rootMat);
        rootMesh.position.set(set.x + dirX * 3, set.y + 3, set.z + dirZ * 3);
        rootMesh.rotation.z = Math.atan2(dirZ, dirX) + Math.PI / 2;
        rootMesh.castShadow = true;
        rootMesh.receiveShadow = true;
        scene.add(rootMesh);
        rootMeshes.push(rootMesh);
      }
    });
  }

  function buildGuardianStatue() {
    // Head
    var headGeo = new THREE.BoxGeometry(2, 3, 1.5);
    var stoneMat = new THREE.MeshStandardMaterial({
      color: 0x9e9891,
      roughness: 0.85,
      metalness: 0.05
    });
    var headMesh = new THREE.Mesh(headGeo, stoneMat);
    headMesh.position.set(-25, 6, -25);
    headMesh.castShadow = true;
    scene.add(headMesh);

    // Body
    var bodyGeo = new THREE.BoxGeometry(2.5, 5, 2);
    var bodyMesh = new THREE.Mesh(bodyGeo, stoneMat);
    bodyMesh.position.set(-25, 3.5, -25);
    bodyMesh.castShadow = true;
    scene.add(bodyMesh);

    // Arms
    for (var i = -1; i <= 1; i += 2) {
      var armGeo = new THREE.BoxGeometry(0.8, 3, 0.8);
      var armMesh = new THREE.Mesh(armGeo, stoneMat);
      armMesh.position.set(-25 + i * 2, 3, -25);
      armMesh.castShadow = true;
      scene.add(armMesh);
    }

    // Weapon (spear) - cylinder
    var spearGeo = new THREE.CylinderGeometry(0.15, 0.2, 8, 6);
    var spearMat = new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.8 });
    var spearMesh = new THREE.Mesh(spearGeo, spearMat);
    spearMesh.position.set(-22, 5, -25);
    spearMesh.rotation.z = 0.3;
    spearMesh.castShadow = true;
    scene.add(spearMesh);

    // Spear head (cone)
    var spearHeadGeo = new THREE.ConeGeometry(0.4, 1.5, 6);
    var spearHeadMesh = new THREE.Mesh(spearHeadGeo, spearMat);
    spearHeadMesh.position.set(-22, 9, -25);
    spearHeadMesh.rotation.z = 0.3;
    spearHeadMesh.castShadow = true;
    scene.add(spearHeadMesh);
  }

  function buildHiddenPassage() {
    // Tunnel entrance hidden in ruins
    var tunnelGeo = new THREE.BoxGeometry(3, 3.5, 2);
    var darkMat = new THREE.MeshStandardMaterial({
      color: 0x3a3a3a,
      roughness: 0.9,
      metalness: 0
    });
    var tunnelMesh = new THREE.Mesh(tunnelGeo, darkMat);
    tunnelMesh.position.set(15, 2, 25);
    tunnelMesh.castShadow = true;
    scene.add(tunnelMesh);

    // Vine curtain (LineSegments)
    var vineGeometry = new THREE.BufferGeometry();
    var vinePositions = [];
    var vineCount = 12;
    var vineHeight = 3.5;

    for (var i = 0; i < vineCount; i++) {
      var xOffset = -1.5 + (i / vineCount) * 3;
      vinePositions.push(15 + xOffset, 3.5, 25);
      vinePositions.push(15 + xOffset + (Math.random() - 0.5) * 0.3, 0, 25);
    }

    vineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vinePositions), 3));
    var vineMat = new THREE.LineBasicMaterial({ color: 0x4a6b4a, linewidth: 2 });
    var vineCurtain = new THREE.LineSegments(vineGeometry, vineMat);
    scene.add(vineCurtain);
    vineMeshes.push(vineCurtain);
  }

  function buildCourtyard() {
    // Cracked stone floor tiles
    var tileSize = 2;
    var gridSize = 10;

    for (var x = -gridSize; x < gridSize; x += tileSize) {
      for (var z = -gridSize; z < gridSize; z += tileSize) {
        var tileGeo = new THREE.BoxGeometry(tileSize * 0.9, 0.3, tileSize * 0.9);
        var crackColor = Math.random() > 0.8 ? 0x5a5a5a : 0x7a7a7a;
        var tileMat = new THREE.MeshStandardMaterial({
          color: crackColor,
          roughness: 0.85,
          metalness: 0
        });
        var tileMesh = new THREE.Mesh(tileGeo, tileMat);
        tileMesh.position.set(x, 0.15, z);
        tileMesh.receiveShadow = true;
        scene.add(tileMesh);

        // Plants sprouting from cracks
        if (Math.random() > 0.7) {
          var plantGeo = new THREE.CylinderGeometry(0.3, 0.4, 1.5, 4);
          var plantMat = new THREE.MeshStandardMaterial({
            color: 0x5d7a60,
            roughness: 0.7
          });
          var plantMesh = new THREE.Mesh(plantGeo, plantMat);
          plantMesh.position.set(x, 0.75, z);
          plantMesh.castShadow = true;
          scene.add(plantMesh);
        }
      }
    }
  }

  function buildTreasureChambel() {
    // Underground chamber walls
    var chamberGeo = new THREE.BoxGeometry(12, 6, 12);
    var chamberMat = new THREE.MeshStandardMaterial({
      color: 0x4a4a4a,
      roughness: 0.9,
      metalness: 0
    });
    var chamberMesh = new THREE.Mesh(chamberGeo, chamberMat);
    chamberMesh.position.set(0, -5, 0);
    chamberMesh.castShadow = true;
    scene.add(chamberMesh);

    // Glowing gems
    var gemPositions = [
      { x: -3, y: -3, z: -3 },
      { x: 3, y: -3, z: -3 },
      { x: 0, y: -4, z: 3 },
      { x: -2, y: -2, z: 0 },
      { x: 2, y: -2, z: 0 }
    ];

    gemPositions.forEach(function(pos) {
      var gemGeo = new THREE.SphereGeometry(0.6, 12, 12);
      var gemMat = new THREE.MeshStandardMaterial({
        color: 0xffd700,
        roughness: 0.3,
        metalness: 0.8,
        emissive: 0xffaa00,
        emissiveIntensity: 0.5
      });
      var gemMesh = new THREE.Mesh(gemGeo, gemMat);
      gemMesh.position.set(pos.x, pos.y, pos.z);
      gemMesh.castShadow = true;
      scene.add(gemMesh);
      gemMeshes.push({ mesh: gemMesh, baseIntensity: 0.5 });
    });

    // Gold pile under gems
    var goldGeo = new THREE.ConeGeometry(2, 1, 8);
    var goldMat = new THREE.MeshStandardMaterial({
      color: 0xdaa520,
      roughness: 0.6,
      metalness: 0.6,
      emissive: 0xaa8800,
      emissiveIntensity: 0.2
    });
    var goldMesh = new THREE.Mesh(goldGeo, goldMat);
    goldMesh.position.set(0, -3.5, 0);
    goldMesh.castShadow = true;
    scene.add(goldMesh);
  }

  function buildJaguars() {
    var jaguarPositions = [
      { x: 30, y: 15, z: -15 },
      { x: -35, y: 18, z: 5 },
      { x: 10, y: 12, z: 40 }
    ];

    jaguarPositions.forEach(function(pos) {
      // Body
      var bodyGeo = new THREE.BoxGeometry(1.5, 1, 3);
      var jaguarMat = new THREE.MeshStandardMaterial({
        color: 0x4a3a2a,
        roughness: 0.7,
        metalness: 0
      });
      var bodyMesh = new THREE.Mesh(bodyGeo, jaguarMat);
      bodyMesh.position.set(pos.x, pos.y, pos.z);
      bodyMesh.castShadow = true;
      scene.add(bodyMesh);

      // Head
      var headGeo = new THREE.SphereGeometry(0.6, 6, 6);
      var headMesh = new THREE.Mesh(headGeo, jaguarMat);
      headMesh.position.set(pos.x, pos.y + 0.3, pos.z + 1.5);
      headMesh.castShadow = true;
      scene.add(headMesh);

      // Tail
      var tailGeo = new THREE.CylinderGeometry(0.25, 0.15, 2, 4);
      var tailMesh = new THREE.Mesh(tailGeo, jaguarMat);
      tailMesh.position.set(pos.x, pos.y - 0.3, pos.z - 1.5);
      tailMesh.rotation.z = 0.4;
      tailMesh.castShadow = true;
      scene.add(tailMesh);

      // Spot markings (small spheres)
      for (var i = 0; i < 3; i++) {
        var spotGeo = new THREE.SphereGeometry(0.25, 4, 4);
        var spotMat = new THREE.MeshStandardMaterial({
          color: 0x2a1a0a,
          roughness: 0.8
        });
        var spotMesh = new THREE.Mesh(spotGeo, spotMat);
        spotMesh.position.set(pos.x + (Math.random() - 0.5), pos.y + Math.random(), pos.z + (Math.random() - 0.5) * 2);
        scene.add(spotMesh);
      }
    });
  }

  function buildHangingVines() {
    var vineStartPositions = [
      { x: 30, z: -20 },
      { x: -30, z: 10 },
      { x: 8, z: 35 },
      { x: -15, z: -30 },
      { x: 0, z: 0 }
    ];

    vineStartPositions.forEach(function(start) {
      var vineGeometry = new THREE.BufferGeometry();
      var positions = [];
      var segments = 20;

      for (var i = 0; i <= segments; i++) {
        var progress = i / segments;
        var yPos = 30 - progress * 30;
        var swayAmount = Math.sin(progress * Math.PI) * 2;
        var xPos = start.x + swayAmount;
        var zPos = start.z + Math.cos(progress * Math.PI) * 1;

        positions.push(xPos, yPos, zPos);
      }

      vineGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
      var vineMat = new THREE.LineBasicMaterial({ color: 0x4a6b4a, linewidth: 1 });
      var vineMesh = new THREE.LineSegments(vineGeometry, vineMat);
      scene.add(vineMesh);
      vineMeshes.push(vineMesh);
    });
  }

  function buildFireflies() {
    var fireflySpherePositions = [];
    var fireflyCount = 40;

    for (var i = 0; i < fireflyCount; i++) {
      var x = (Math.random() - 0.5) * 60;
      var y = Math.random() * 30 + 5;
      var z = (Math.random() - 0.5) * 60;

      var ffGeo = new THREE.SphereGeometry(0.15, 4, 4);
      var ffMat = new THREE.MeshStandardMaterial({
        color: 0xffff99,
        roughness: 0.2,
        metalness: 0.8,
        emissive: 0xffff00,
        emissiveIntensity: 0.8
      });
      var ffMesh = new THREE.Mesh(ffGeo, ffMat);
      ffMesh.position.set(x, y, z);
      scene.add(ffMesh);

      fireflyMeshes.push({
        mesh: ffMesh,
        startPos: { x: x, y: y, z: z },
        phase: Math.random() * Math.PI * 2
      });
    }
  }

  function update(delta) {
    time += delta;

    // Sway hanging vines
    vineMeshes.forEach(function(vine, idx) {
      var positions = vine.geometry.attributes.position.array;
      var segments = (positions.length / 3) - 1;

      for (var i = 0; i <= segments; i++) {
        var progress = i / segments;
        var sway = Math.sin(time * 0.8 + idx) * 0.5 * (1 - progress);
        var basePos = vine.userData.basePositions ? vine.userData.basePositions[i * 3] : positions[i * 3];
        positions[i * 3] += sway * delta;
      }

      vine.geometry.attributes.position.needsUpdate = true;
    });

    // Animate fireflies drifting
    fireflyMeshes.forEach(function(ff) {
      var drift = Math.sin(time + ff.phase) * 2;
      var driftUp = Math.cos(time * 0.5 + ff.phase) * 1.5;
      var driftZ = Math.sin(time * 0.7 + ff.phase) * 2;

      ff.mesh.position.x = ff.startPos.x + drift;
      ff.mesh.position.y = ff.startPos.y + driftUp;
      ff.mesh.position.z = ff.startPos.z + driftZ;

      // Pulse glow
      var glowPulse = 0.5 + Math.sin(time * 3 + ff.phase) * 0.4;
      ff.mesh.material.emissiveIntensity = glowPulse;
    });

    // Gem glow pulse
    gemMeshes.forEach(function(gem, idx) {
      var pulseSin = Math.sin(time * 1.2 + idx) * 0.3;
      gem.mesh.material.emissiveIntensity = gem.baseIntensity + pulseSin;
      gem.mesh.rotation.x += 0.01;
      gem.mesh.rotation.y += 0.015;
    });

    // Root creep animation
    rootMeshes.forEach(function(root, idx) {
      var creep = Math.sin(time * 0.3 + idx) * 0.3;
      root.position.y += creep * delta * 0.1;
    });
  }

  function reset() {
    time = 0;
    vineMeshes.forEach(function(vine) {
      if (vine.geometry) vine.geometry.dispose();
      if (vine.material) vine.material.dispose();
    });
    vineMeshes = [];

    fireflyMeshes = [];
    gemMeshes = [];
    rootMeshes = [];
  }

  return {
    init: init,
    update: update,
    reset: reset
  };
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail jungle-ruin.js",_e&&_e.message); }
/* === sky-carrier.js === */
try {
;
window.SkyCarrier = (function() {
	'use strict';

	var scene = null;
	var camera = null;

	var flightDeck = null;
	var controlIsland = null;
	var radarDish = null;
	var fighterJets = [];
	var aaGunTurrets = [];
	var launchCatapult = null;
	var arrestingWires = null;
	var safetyNets = null;
	var engineNacelles = [];
	var cloudMasses = [];
	var elevatorPlatform = null;
	var hangarBayEntrance = null;
	var windParticles = [];

	var elevatorHeight = 0;
	var elevatorDirection = 1;
	var radarRotation = 0;
	var cloudDriftX = 0;
	var particleSpeed = 0;

	function init(initScene, initCamera) {
		scene = initScene;
		camera = initCamera;

		buildFlightDeck();
		buildControlIsland();
		buildFighterJets();
		buildAAGunTurrets();
		buildLaunchCatapult();
		buildArrestingWires();
		buildSafetyNets();
		buildEnginePropulsion();
		buildCloudLayer();
		buildElevatorPlatform();
		buildHangarBayEntrance();
		buildWindParticles();

		return true;
	}

	function buildFlightDeck() {
		var deckGeometry = new THREE.BoxGeometry(220, 15, 320);
		var deckMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.6 });
		flightDeck = new THREE.Mesh(deckGeometry, deckMaterial);
		flightDeck.position.set(0, 50, 0);
		flightDeck.castShadow = true;
		flightDeck.receiveShadow = true;
		scene.add(flightDeck);

		var hullGeometry = new THREE.BoxGeometry(200, 40, 280);
		var hullMaterial = new THREE.MeshStandardMaterial({ color: 0x2c2c2c, metalness: 0.5 });
		var hull = new THREE.Mesh(hullGeometry, hullMaterial);
		hull.position.set(0, 15, 0);
		hull.castShadow = true;
		hull.receiveShadow = true;
		scene.add(hull);

		var bowGeometry = new THREE.ConeGeometry(25, 30, 16);
		var bowMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
		var bow = new THREE.Mesh(bowGeometry, bowMaterial);
		bow.position.set(0, 20, 160);
		bow.castShadow = true;
		scene.add(bow);
	}

	function buildControlIsland() {
		var islandGeometry = new THREE.BoxGeometry(35, 50, 25);
		var islandMaterial = new THREE.MeshStandardMaterial({ color: 0x4a4a4a, metalness: 0.4 });
		controlIsland = new THREE.Mesh(islandGeometry, islandMaterial);
		controlIsland.position.set(85, 85, -80);
		controlIsland.castShadow = true;
		controlIsland.receiveShadow = true;
		scene.add(controlIsland);

		var radarGeometry = new THREE.CylinderGeometry(12, 12, 4, 32);
		var radarMaterial = new THREE.MeshStandardMaterial({ color: 0xffa500, emissive: 0xff6600 });
		radarDish = new THREE.Mesh(radarGeometry, radarMaterial);
		radarDish.position.set(85, 140, -80);
		radarDish.castShadow = true;
		scene.add(radarDish);

		var antennaGeometry = new THREE.CylinderGeometry(1, 1, 20, 8);
		var antennaMaterial = new THREE.MeshStandardMaterial({ color: 0x999999 });
		var antenna = new THREE.Mesh(antennaGeometry, antennaMaterial);
		antenna.position.set(85, 155, -80);
		scene.add(antenna);

		var bridgeGeometry = new THREE.BoxGeometry(30, 12, 20);
		var bridgeMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
		var bridge = new THREE.Mesh(bridgeGeometry, bridgeMaterial);
		bridge.position.set(85, 125, -80);
		bridge.castShadow = true;
		scene.add(bridge);
	}

	function buildFighterJets() {
		var jetPositions = [
			{ x: -60, z: 20 },
			{ x: -60, z: 60 },
			{ x: 60, z: 20 },
			{ x: 60, z: 60 },
			{ x: -30, z: -40 },
			{ x: 30, z: -40 }
		];

		var jetCount = 0;
		for (var i = 0; i < jetPositions.length; i++) {
			if (jetCount >= 6) break;

			var jetGroup = new THREE.Group();
			jetGroup.position.set(jetPositions[i].x, 58, jetPositions[i].z);

			var fuselageGeometry = new THREE.BoxGeometry(3, 4, 12);
			var fuselageMaterial = new THREE.MeshStandardMaterial({ color: 0x1a3a52, metalness: 0.7 });
			var fuselage = new THREE.Mesh(fuselageGeometry, fuselageMaterial);
			fuselage.castShadow = true;
			jetGroup.add(fuselage);

			var noseGeometry = new THREE.ConeGeometry(1.5, 4, 16);
			var noseMaterial = new THREE.MeshStandardMaterial({ color: 0x0d1f2d });
			var nose = new THREE.Mesh(noseGeometry, noseMaterial);
			nose.position.z = 6;
			nose.castShadow = true;
			jetGroup.add(nose);

			var engine1Geometry = new THREE.CylinderGeometry(0.8, 0.8, 3, 16);
			var engineMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.8 });
			var engine1 = new THREE.Mesh(engine1Geometry, engineMaterial);
			engine1.position.set(-1.5, -2, -2);
			engine1.castShadow = true;
			jetGroup.add(engine1);

			var engine2 = new THREE.Mesh(engine1Geometry, engineMaterial);
			engine2.position.set(1.5, -2, -2);
			engine2.castShadow = true;
			jetGroup.add(engine2);

			var wingGeometry = new THREE.BoxGeometry(10, 0.5, 2);
			var wingMaterial = new THREE.MeshStandardMaterial({ color: 0x1a3a52 });
			var wings = new THREE.Mesh(wingGeometry, wingMaterial);
			wings.position.y = 0.5;
			wings.castShadow = true;
			jetGroup.add(wings);

			scene.add(jetGroup);
			fighterJets.push(jetGroup);
			jetCount++;
		}
	}

	function buildAAGunTurrets() {
		var turretPositions = [
			{ x: -90, z: 100 },
			{ x: 90, z: 100 },
			{ x: -90, z: -100 },
			{ x: 90, z: -100 },
			{ x: -70, z: 50 },
			{ x: 70, z: 50 }
		];

		for (var i = 0; i < turretPositions.length; i++) {
			var turretGroup = new THREE.Group();
			turretGroup.position.set(turretPositions[i].x, 62, turretPositions[i].z);

			var baseGeometry = new THREE.BoxGeometry(8, 4, 8);
			var baseMaterial = new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.5 });
			var base = new THREE.Mesh(baseGeometry, baseMaterial);
			base.castShadow = true;
			turretGroup.add(base);

			var crewGeometry = new THREE.CylinderGeometry(4, 4, 2, 16);
			var crewMaterial = new THREE.MeshStandardMaterial({ color: 0x666666 });
			var crew = new THREE.Mesh(crewGeometry, crewMaterial);
			crew.position.y = 3;
			crew.castShadow = true;
			turretGroup.add(crew);

			var barrelGeometry = new THREE.CylinderGeometry(0.6, 0.6, 6, 16);
			var barrelMaterial = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.9 });
			var barrel = new THREE.Mesh(barrelGeometry, barrelMaterial);
			barrel.position.set(0, 4.5, 0);
			barrel.rotation.z = Math.PI / 6;
			barrel.castShadow = true;
			turretGroup.add(barrel);

			turretGroup.rotationSpeed = Math.random() * 0.01 + 0.005;
			turretGroup.currentRotation = Math.random() * Math.PI * 2;

			scene.add(turretGroup);
			aaGunTurrets.push(turretGroup);
		}
	}

	function buildLaunchCatapult() {
		var railGeometry = new THREE.BoxGeometry(2, 0.8, 280);
		var railMaterial = new THREE.MeshStandardMaterial({ color: 0x999999, metalness: 0.7 });
		var rail = new THREE.Mesh(railGeometry, railMaterial);
		rail.position.set(0, 51, 0);
		rail.castShadow = true;
		scene.add(rail);

		var points = [];
		points.push(new THREE.Vector3(-1, 51.5, -140));
		points.push(new THREE.Vector3(-1, 51.5, 140));

		var catapultGeometry = new THREE.LineSegments(
			new THREE.BufferGeometry().setFromPoints(points),
			new THREE.LineBasicMaterial({ color: 0xffff00, linewidth: 3 })
		);
		launchCatapult = catapultGeometry;
		scene.add(launchCatapult);

		points = [];
		points.push(new THREE.Vector3(1, 51.5, -140));
		points.push(new THREE.Vector3(1, 51.5, 140));

		var catapult2Geometry = new THREE.LineSegments(
			new THREE.BufferGeometry().setFromPoints(points),
			new THREE.LineBasicMaterial({ color: 0xffff00, linewidth: 3 })
		);
		scene.add(catapult2Geometry);
	}

	function buildArrestingWires() {
		var points = [];
		for (var i = 0; i < 5; i++) {
			var z = -140 + i * 30;
			points.push(new THREE.Vector3(-110, 51, z));
			points.push(new THREE.Vector3(110, 51, z));
		}

		arrestingWires = new THREE.LineSegments(
			new THREE.BufferGeometry().setFromPoints(points),
			new THREE.LineBasicMaterial({ color: 0x00ff00, linewidth: 2 })
		);
		scene.add(arrestingWires);
	}

	function buildSafetyNets() {
		var points = [];
		var spacing = 10;
		var height = 15;

		for (var i = 0; i < 35; i += spacing) {
			points.push(new THREE.Vector3(-110, 50, -140 + i));
			points.push(new THREE.Vector3(-110, 50 + height, -140 + i));
		}

		for (var i = 0; i < 35; i += spacing) {
			points.push(new THREE.Vector3(110, 50, -140 + i));
			points.push(new THREE.Vector3(110, 50 + height, -140 + i));
		}

		safetyNets = new THREE.LineSegments(
			new THREE.BufferGeometry().setFromPoints(points),
			new THREE.LineBasicMaterial({ color: 0x888888, linewidth: 1 })
		);
		scene.add(safetyNets);
	}

	function buildEnginePropulsion() {
		var nacellePairPositions = [
			{ x: -50, z: -80 },
			{ x: 50, z: -80 }
		];

		for (var i = 0; i < nacellePairPositions.length; i++) {
			var nacelleGeometry = new THREE.CylinderGeometry(8, 8, 25, 16);
			var nacelleMount = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.8 });
			var nacelle = new THREE.Mesh(nacelleGeometry, nacelleMount);
			nacelle.position.set(nacellePairPositions[i].x, 5, nacellePairPositions[i].z);
			nacelle.castShadow = true;
			nacelle.receiveShadow = true;
			scene.add(nacelle);
			engineNacelles.push(nacelle);
		}
	}

	function buildCloudLayer() {
		var cloudCount = 12;
		for (var i = 0; i < cloudCount; i++) {
			var cloudGeometry = new THREE.SphereGeometry(15 + Math.random() * 15, 12, 8);
			var cloudMaterial = new THREE.MeshStandardMaterial({
				color: 0xcccccc,
				emissive: 0x666666,
				transparent: true,
				opacity: 0.7,
				metalness: 0
			});
			var cloudMesh = new THREE.Mesh(cloudGeometry, cloudMaterial);

			var cloudX = (Math.random() - 0.5) * 600;
			var cloudY = -80 + Math.random() * 40;
			var cloudZ = -200 + Math.random() * 400;

			cloudMesh.position.set(cloudX, cloudY, cloudZ);
			cloudMesh.castShadow = false;
			cloudMesh.receiveShadow = false;

			cloudMesh.driftSpeed = (Math.random() - 0.5) * 8;
			cloudMesh.baseX = cloudX;

			scene.add(cloudMesh);
			cloudMasses.push(cloudMesh);
		}
	}

	function buildElevatorPlatform() {
		var elevatorGeometry = new THREE.BoxGeometry(30, 2, 25);
		var elevatorMaterial = new THREE.MeshStandardMaterial({ color: 0x777777, metalness: 0.6 });
		elevatorPlatform = new THREE.Mesh(elevatorGeometry, elevatorMaterial);
		elevatorPlatform.position.set(-70, 51, 80);
		elevatorPlatform.castShadow = true;
		elevatorPlatform.receiveShadow = true;
		scene.add(elevatorPlatform);

		var elevatorShaftGeometry = new THREE.BoxGeometry(32, 40, 27);
		var shaftMaterial = new THREE.MeshStandardMaterial({ color: 0x444444, metalness: 0.3 });
		var shaft = new THREE.Mesh(elevatorShaftGeometry, shaftMaterial);
		shaft.position.set(-70, 25, 80);
		shaft.castShadow = true;
		scene.add(shaft);
	}

	function buildHangarBayEntrance() {
		var entranceGeometry = new THREE.BoxGeometry(50, 25, 8);
		var entranceMaterial = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.7 });
		hangarBayEntrance = new THREE.Mesh(entranceGeometry, entranceMaterial);
		hangarBayEntrance.position.set(0, 35, -145);
		hangarBayEntrance.castShadow = true;
		hangarBayEntrance.receiveShadow = true;
		scene.add(hangarBayEntrance);

		var hangarInteriorGeometry = new THREE.BoxGeometry(48, 23, 35);
		var hangarMaterial = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.5 });
		var hangarInterior = new THREE.Mesh(hangarInteriorGeometry, hangarMaterial);
		hangarInterior.position.set(0, 35, -175);
		hangarInterior.castShadow = true;
		scene.add(hangarInterior);

		var hangarLightGeometry = new THREE.BoxGeometry(40, 2, 30);
		var lightMaterial = new THREE.MeshStandardMaterial({ color: 0xffff99, emissive: 0xffcc00 });
		var hangarLight = new THREE.Mesh(hangarLightGeometry, lightMaterial);
		hangarLight.position.set(0, 45, -175);
		hangarLight.castShadow = false;
		scene.add(hangarLight);
	}

	function buildWindParticles() {
		var particleCount = 30;
		for (var i = 0; i < particleCount; i++) {
			var particleGeometry = new THREE.SphereGeometry(0.5, 4, 4);
			var particleMaterial = new THREE.MeshStandardMaterial({
				color: 0xdddddd,
				emissive: 0x999999,
				transparent: true,
				opacity: 0.4
			});
			var particle = new THREE.Mesh(particleGeometry, particleMaterial);

			var px = Math.random() * 300 - 150;
			var py = 20 + Math.random() * 100;
			var pz = -200 + Math.random() * 400;

			particle.position.set(px, py, pz);
			particle.castShadow = false;
			particle.receiveShadow = false;

			particle.velocity = (Math.random() - 0.5) * 60 + 30;
			particle.baseY = py;

			scene.add(particle);
			windParticles.push(particle);
		}
	}

	function update(delta) {
		if (!scene) return;

		elevatorHeight += elevatorDirection * 20 * delta;
		if (elevatorHeight > 8 || elevatorHeight < 0) {
			elevatorDirection *= -1;
		}
		if (elevatorPlatform) {
			elevatorPlatform.position.y = 51 + elevatorHeight;
		}

		radarRotation += 0.5 * delta;
		if (radarDish) {
			radarDish.rotation.z = radarRotation;
		}

		for (var i = 0; i < aaGunTurrets.length; i++) {
			var turret = aaGunTurrets[i];
			turret.currentRotation += turret.rotationSpeed;
			turret.rotation.y = turret.currentRotation;
		}

		cloudDriftX += 8 * delta;
		for (var i = 0; i < cloudMasses.length; i++) {
			var cloud = cloudMasses[i];
			cloud.position.x = cloud.baseX + cloudDriftX + cloud.driftSpeed * cloudDriftX * 0.05;

			if (cloud.position.x > 350) {
				cloud.position.x = -350;
			}
			if (cloud.position.x < -350) {
				cloud.position.x = 350;
			}
		}

		particleSpeed = (particleSpeed + 60 * delta) % 600;
		for (var i = 0; i < windParticles.length; i++) {
			var p = windParticles[i];
			p.position.x += p.velocity * delta;

			if (p.position.x > 180) {
				p.position.x = -180;
			}
			if (p.position.x < -180) {
				p.position.x = 180;
			}

			var wobble = Math.sin(particleSpeed * 0.01 + i) * 2;
			p.position.y = p.baseY + wobble;
		}

		for (var i = 0; i < fighterJets.length; i++) {
			var jet = fighterJets[i];
			jet.rotation.z = Math.sin(Date.now() * 0.0001) * 0.05;
		}
	}

	function reset() {
		elevatorHeight = 0;
		elevatorDirection = 1;
		radarRotation = 0;
		cloudDriftX = 0;
		particleSpeed = 0;

		if (elevatorPlatform) {
			elevatorPlatform.position.y = 51;
		}

		for (var i = 0; i < cloudMasses.length; i++) {
			cloudMasses[i].position.x = cloudMasses[i].baseX;
		}

		for (var i = 0; i < windParticles.length; i++) {
			windParticles[i].position.x = (Math.random() - 0.5) * 360;
		}
	}

	return {
		init: init,
		update: update,
		reset: reset
	};
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail sky-carrier.js",_e&&_e.message); }
