      var plantGeom = new THREE.ConeGeometry(2, 4, 6);
      var plant = new THREE.Mesh(plantGeom, new THREE.MeshPhongMaterial({ color: 0x2d5016 }));
      plant.position.set(-15 + n * 8, 2.5, -50);
      scene.add(plant);
