/* === cliff-village.js === */
try {
;
window.CliffVillage = (function() {
	'use strict';

	var scene = null;
	var camera = null;
	var objects = [];
	var firePits = [];
	var bridgeSegments = [];
	var dustParticles = [];
	var elapsedTime = 0;
	var particleCount = 0;

	function init(sceneRef, cameraRef) {
		scene = sceneRef;
		camera = cameraRef;
		objects = [];
		firePits = [];
		bridgeSegments = [];
		dustParticles = [];
		elapsedTime = 0;
		particleCount = 0;

		// Canyon wall - massive terracotta rock face
		var canyonWall = new THREE.Mesh(
			new THREE.BoxGeometry(120, 150, 40),
			new THREE.MeshPhongMaterial({ color: 0xc1440e, flatShading: true })
		);
		canyonWall.position.set(0, 40, -10);
		canyonWall.castShadow = true;
		scene.add(canyonWall);
		objects.push(canyonWall);

		// Canyon floor - dry riverbed
		var canyonFloor = new THREE.Mesh(
			new THREE.BoxGeometry(120, 8, 80),
			new THREE.MeshPhongMaterial({ color: 0x8b7355 })
		);
		canyonFloor.position.set(0, -60, 0);
		canyonFloor.castShadow = true;
		scene.add(canyonFloor);
		objects.push(canyonFloor);

		// Natural rock ledges - protruding platforms
		var ledgePositions = [
			{ x: -20, y: 20, z: 0, width: 30, depth: 20 },
			{ x: 15, y: -5, z: 0, width: 35, depth: 22 },
			{ x: -25, y: -20, z: 0, width: 28, depth: 18 },
			{ x: 20, y: 35, z: 0, width: 32, depth: 20 }
		];

		for (var i = 0; i < ledgePositions.length; i++) {
			var ledge = new THREE.Mesh(
				new THREE.BoxGeometry(ledgePositions[i].width, 6, ledgePositions[i].depth),
				new THREE.MeshPhongMaterial({ color: 0xa0522d })
			);
			ledge.position.set(ledgePositions[i].x, ledgePositions[i].y, ledgePositions[i].z);
			ledge.castShadow = true;
			scene.add(ledge);
			objects.push(ledge);
		}

		// Cliff dwellings - pueblo-style buildings
		var dwellingConfigs = [
			{ x: -15, y: 25, z: 2, w: 16, h: 14, d: 12 },
			{ x: 10, y: 0, z: 2, w: 18, h: 12, d: 14 },
			{ x: -20, y: -15, z: 2, w: 14, h: 10, d: 10 },
			{ x: 18, y: 40, z: 2, w: 16, h: 13, d: 12 }
		];

		for (var i = 0; i < dwellingConfigs.length; i++) {
			var cfg = dwellingConfigs[i];
			var dwelling = new THREE.Mesh(
				new THREE.BoxGeometry(cfg.w, cfg.h, cfg.d),
				new THREE.MeshPhongMaterial({ color: 0xd4956e })
			);
			dwelling.position.set(cfg.x, cfg.y, cfg.z);
			dwelling.castShadow = true;
			scene.add(dwelling);
			objects.push(dwelling);

			// Add defensive arrow loops to dwelling
			addArrowLoops(dwelling, cfg.w, cfg.h);
		}

		// Grain storage towers - cylindrical structures
		var towerPositions = [
			{ x: -30, y: 15, z: 0 },
			{ x: 25, y: -10, z: 0 },
			{ x: 0, y: 30, z: 0 }
		];

		for (var i = 0; i < towerPositions.length; i++) {
			var tower = new THREE.Mesh(
				new THREE.CylinderGeometry(5, 6, 18, 8),
				new THREE.MeshPhongMaterial({ color: 0xb8860b })
			);
			tower.position.set(towerPositions[i].x, towerPositions[i].y, towerPositions[i].z);
			tower.castShadow = true;
			scene.add(tower);
			objects.push(tower);
		}

		// Ceremonial kiva - underground circular room
		var kiva = new THREE.Mesh(
			new THREE.CylinderGeometry(12, 13, 8, 16),
			new THREE.MeshPhongMaterial({ color: 0x654321 })
		);
		kiva.position.set(-5, -50, 5);
		kiva.castShadow = true;
		scene.add(kiva);
		objects.push(kiva);

		// Ladders between levels
		addLadderSystem(-15, 25, 2, 10);
		addLadderSystem(10, 0, 2, 12);
		addLadderSystem(-20, -15, 2, 8);

		// Rope suspension bridges
		addBridge(-15, 10, 0, 10, 15, 2);
		addBridge(15, 30, 0, 5, 10, 1);

		// Fire pits on ledges
		addFirePit(-15, 21, 4);
		addFirePit(10, -4, 4);
		addFirePit(-20, -19, 4);
		addFirePit(18, 36, 4);

		// Wind erosion arch formations
		addArch(-35, 50, -5, 20, 25, 8);
		addArch(30, 60, -8, 18, 22, 7);

		return true;
	}

	function addArrowLoops(dwelling, width, height) {
		var loopSize = 1.5;
		var loopDepth = 2;
		var halfW = width / 2;
		var halfH = height / 2;

		// Front face arrow loops
		var loop1 = new THREE.Mesh(
			new THREE.BoxGeometry(loopSize, loopSize, loopDepth),
			new THREE.MeshPhongMaterial({ color: 0x444444 })
		);
		loop1.position.set(dwelling.position.x - halfW + 2, dwelling.position.y + halfH - 4, dwelling.position.z + (dwelling.geometry.parameters.depth / 2));
		scene.add(loop1);
		objects.push(loop1);

		var loop2 = new THREE.Mesh(
			new THREE.BoxGeometry(loopSize, loopSize, loopDepth),
			new THREE.MeshPhongMaterial({ color: 0x444444 })
		);
		loop2.position.set(dwelling.position.x + halfW - 2, dwelling.position.y + halfH - 4, dwelling.position.z + (dwelling.geometry.parameters.depth / 2));
		scene.add(loop2);
		objects.push(loop2);
	}

	function addLadderSystem(x, y, z, height) {
		var rungCount = Math.floor(height / 1.5);
		var poleRadius = 0.4;
		var poleSpacing = 2;

		// Left pole
		var leftPole = new THREE.Mesh(
			new THREE.CylinderGeometry(poleRadius, poleRadius, height, 6),
			new THREE.MeshPhongMaterial({ color: 0x8b6914 })
		);
		leftPole.position.set(x - poleSpacing / 2, y - height / 2, z);
		leftPole.castShadow = true;
		scene.add(leftPole);
		objects.push(leftPole);

		// Right pole
		var rightPole = new THREE.Mesh(
			new THREE.CylinderGeometry(poleRadius, poleRadius, height, 6),
			new THREE.MeshPhongMaterial({ color: 0x8b6914 })
		);
		rightPole.position.set(x + poleSpacing / 2, y - height / 2, z);
		rightPole.castShadow = true;
		scene.add(rightPole);
		objects.push(rightPole);

		// Rungs as line segments
		var rungVertices = [];
		for (var i = 0; i < rungCount; i++) {
			var rungY = y + height / 2 - i * 1.5;
			rungVertices.push(new THREE.Vector3(x - poleSpacing / 2, rungY, z));
			rungVertices.push(new THREE.Vector3(x + poleSpacing / 2, rungY, z));
		}

		if (rungVertices.length > 0) {
			var rungGeometry = new THREE.BufferGeometry().setFromPoints(rungVertices);
			var rungLines = new THREE.LineSegments(
				rungGeometry,
				new THREE.LineBasicMaterial({ color: 0x8b6914, linewidth: 2 })
			);
			scene.add(rungLines);
			objects.push(rungLines);
		}
	}

	function addBridge(x1, y1, z1, x2, y2, z2) {
		var cableStart = new THREE.Vector3(x1, y1, z1);
		var cableEnd = new THREE.Vector3(x2, y2, z2);

		// Cable lines
		var cableVertices = [
			new THREE.Vector3(x1, y1 - 2, z1),
			new THREE.Vector3(x2, y2 - 2, z2),
			new THREE.Vector3(x1, y1 - 2, z1),
			new THREE.Vector3(x2, y2 - 2, z2)
		];

		var cableGeometry = new THREE.BufferGeometry().setFromPoints(cableVertices);
		var cables = new THREE.LineSegments(
			cableGeometry,
			new THREE.LineBasicMaterial({ color: 0x8b4513, linewidth: 3 })
		);
		scene.add(cables);
		objects.push(cables);

		// Bridge planks
		var bridgeMidX = (x1 + x2) / 2;
		var bridgeMidY = (y1 + y2) / 2;
		var bridgeLength = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
		var bridgeAngle = Math.atan2(y2 - y1, x2 - x1);

		var plank = new THREE.Mesh(
			new THREE.BoxGeometry(bridgeLength, 1, 1.5),
			new THREE.MeshPhongMaterial({ color: 0x8b6914 })
		);
		plank.position.set(bridgeMidX, bridgeMidY, z1);
		plank.rotation.z = bridgeAngle;
		plank.castShadow = true;
		scene.add(plank);
		objects.push(plank);

		bridgeSegments.push({
			mesh: plank,
			baseRotation: bridgeAngle
		});
	}

	function addFirePit(x, y, z) {
		// Pit container
		var pit = new THREE.Mesh(
			new THREE.BoxGeometry(4, 1, 4),
			new THREE.MeshPhongMaterial({ color: 0x2a2a2a })
		);
		pit.position.set(x, y, z);
		scene.add(pit);
		objects.push(pit);

		// Embers
		var embers = new THREE.Mesh(
			new THREE.SphereGeometry(1.5, 8, 8),
			new THREE.MeshBasicMaterial({ color: 0xff6600 })
		);
		embers.position.set(x, y + 1, z);
		scene.add(embers);
		objects.push(embers);

		firePits.push({
			embers: embers,
			pit: pit,
			baseIntensity: 1,
			phase: Math.random() * Math.PI * 2
		});
	}

	function addArch(x, y, z, width, height, depth) {
		// Arch formation - combination of boxes to create arch-like shape
		var archCount = 4;
		for (var i = 0; i < archCount; i++) {
			var archX = x - width / 2 + (i * width / archCount) + width / (archCount * 2);
			var archY = y + (Math.sin((i / archCount) * Math.PI) * height * 0.6);

			var archSegment = new THREE.Mesh(
				new THREE.BoxGeometry(width / archCount - 1, 8, depth),
				new THREE.MeshPhongMaterial({ color: 0xb8860b })
			);
			archSegment.position.set(archX, archY, z);
			archSegment.castShadow = true;
			scene.add(archSegment);
			objects.push(archSegment);
		}
	}

	function update(delta) {
		elapsedTime += delta;

		// Animate fire pit glow
		for (var i = 0; i < firePits.length; i++) {
			var fp = firePits[i];
			var glowIntensity = fp.baseIntensity + Math.sin(elapsedTime * 3 + fp.phase) * 0.5;
			fp.embers.material.color.setHex(Math.floor(0xff6600 * (glowIntensity / 1.5)));
			fp.embers.scale.x = 1 + Math.sin(elapsedTime * 2 + fp.phase) * 0.2;
			fp.embers.scale.y = fp.embers.scale.x;
			fp.embers.scale.z = fp.embers.scale.x;
		}

		// Animate rope bridge sway
		for (var i = 0; i < bridgeSegments.length; i++) {
			var bridge = bridgeSegments[i];
			var sway = Math.sin(elapsedTime * 0.8 + i) * 0.15;
			bridge.mesh.rotation.z = bridge.baseRotation + sway;
		}

		// Generate wind-blown dust particles
		if (Math.random() < 0.02) {
			var dustX = (Math.random() - 0.5) * 100;
			var dustY = Math.random() * 80 - 20;
			var dustZ = (Math.random() - 0.5) * 60 - 10;

			var dustParticle = new THREE.Mesh(
				new THREE.SphereGeometry(0.1, 4, 4),
				new THREE.MeshBasicMaterial({ color: 0xd2b48c, transparent: true, opacity: 0.3 })
			);
			dustParticle.position.set(dustX, dustY, dustZ);
			scene.add(dustParticle);

			dustParticles.push({
				mesh: dustParticle,
				velocity: new THREE.Vector3(
					(Math.random() - 0.5) * 2,
					-1,
					(Math.random() - 0.5) * 1
				),
				life: 5
			});
		}

		// Update dust particles
		for (var i = dustParticles.length - 1; i >= 0; i--) {
			var dp = dustParticles[i];
			dp.mesh.position.add(dp.velocity.clone().multiplyScalar(delta));
			dp.life -= delta;
			dp.mesh.material.opacity = (dp.life / 5) * 0.3;

			if (dp.life <= 0) {
				scene.remove(dp.mesh);
				dustParticles.splice(i, 1);
			}
		}
	}

	function reset() {
		while (objects.length > 0) {
			var obj = objects.pop();
			scene.remove(obj);
		}

		while (dustParticles.length > 0) {
			var dp = dustParticles.pop();
			scene.remove(dp.mesh);
		}

		firePits = [];
		bridgeSegments = [];
		elapsedTime = 0;
		particleCount = 0;
	}

	return {
		init: init,
		update: update,
		reset: reset
	};
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail cliff-village.js",_e&&_e.message); }
/* === drone-bay.js === */
try {
;
window.DroneBay = (function() {
	'use strict';

	var scene;
	var camera;
	var patrolDrones = [];
	var assemblyConveyors = [];
	var launchTubes = [];
	var empArcs = [];
	var airlockDoors = [];
	var time = 0;

	var init = function(sceneArg, cameraArg) {
		scene = sceneArg;
		camera = cameraArg;

		// Assembly line area with conveyor belts and drone assembly stations
		createAssemblyLines();

		// Charging rack walls with energy cells
		createChargingRacks();

		// Launch tube array
		createLaunchTubes();

		// Active patrol drones flying overhead
		createPatrolDrones();

		// Control console center
		createControlConsole();

		// Storage shelving area
		createStorageArea();

		// Testing range with target dummies
		createTestingRange();

		// Crash recovery bay
		createCrashBay();

		// EMP shield generators at corners
		createEMPShields();

		// Airlock doors at facility exits
		createAirlockDoors();

		// Ground and floor
		createFloor();

		// Walls and structure
		createWalls();

		// Lighting
		createLighting();
	};

	var createAssemblyLines = function() {
		var lineY = 0.5;
		var lineCount = 3;
		var lineSpacing = 8;
		var startX = -20;
		var lineLength = 40;

		for (var i = 0; i < lineCount; i++) {
			var zPos = startX + (i * lineSpacing);

			// Conveyor belt
			var beltGeom = new THREE.BoxGeometry(lineLength, 0.3, 2);
			var beltMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.7 });
			var belt = new THREE.Mesh(beltGeom, beltMat);
			belt.position.set(0, lineY, zPos);
			scene.add(belt);

			// Conveyor supports
			var supportGeom = new THREE.BoxGeometry(0.5, lineY, 2.5);
			var supportMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
			for (var j = -1; j <= 1; j++) {
				var support = new THREE.Mesh(supportGeom, supportMat);
				support.position.set(startX + (j * 15), lineY * 0.5, zPos);
				scene.add(support);
			}

			// Drone bodies at assembly stages
			var droneSpacing = 4;
			for (var k = 0; k < 3; k++) {
				var droneX = startX + 10 + (k * droneSpacing);
				createPartialDrone(droneX, lineY + 1, zPos, k);
			}

			assemblyConveyors.push({
				belt: belt,
				offset: 0,
				speed: 0.3
			});
		}
	};

	var createPartialDrone = function(x, y, z, stage) {
		// Drone body (BoxGeometry)
		var bodyGeom = new THREE.BoxGeometry(1.5, 1, 2);
		var bodyMat = new THREE.MeshStandardMaterial({
			color: 0xff6600 + (stage * 0x110000),
			metalness: 0.8
		});
		var body = new THREE.Mesh(bodyGeom, bodyMat);
		body.position.set(x, y, z);
		scene.add(body);

		// Rotor arms (stage dependent)
		if (stage >= 1) {
			for (var i = -1; i <= 1; i += 2) {
				var armGeom = new THREE.CylinderGeometry(0.1, 0.1, 2, 8);
				var armMat = new THREE.MeshStandardMaterial({ color: 0xcccccc });
				var arm = new THREE.Mesh(armGeom, armMat);
				arm.position.set(x + (i * 0.8), y + 0.5, z);
				arm.rotation.z = Math.PI * 0.5;
				scene.add(arm);
			}
		}

		// Camera nose (stage dependent)
		if (stage >= 2) {
			var cameraGeom = new THREE.ConeGeometry(0.3, 0.6, 8);
			var cameraMat = new THREE.MeshStandardMaterial({ color: 0x0088ff });
			var camera = new THREE.Mesh(cameraGeom, cameraMat);
			camera.position.set(x, y + 0.3, z + 1.2);
			camera.rotation.x = Math.PI * 0.5;
			scene.add(camera);
		}
	};

	var createChargingRacks = function() {
		var rackX = 25;
		var rackHeight = 10;
		var rackWidth = 12;
		var cellRadius = 0.4;

		// Rack structure
		var rackGeom = new THREE.BoxGeometry(rackWidth, rackHeight, 3);
		var rackMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.6 });
		var rack = new THREE.Mesh(rackGeom, rackMat);
		rack.position.set(rackX, rackHeight * 0.5, 0);
		scene.add(rack);

		// Energy cells (SphereGeometry)
		var cellsPerRow = 4;
		var cellsPerColumn = 5;
		var cellSpacingX = rackWidth / (cellsPerRow + 1);
		var cellSpacingY = rackHeight / (cellsPerColumn + 1);

		for (var y = 0; y < cellsPerColumn; y++) {
			for (var x = 0; x < cellsPerRow; x++) {
				var cellGeom = new THREE.SphereGeometry(cellRadius, 8, 8);
				var cellMat = new THREE.MeshStandardMaterial({
					color: 0x00ff00,
					emissive: 0x00aa00
				});
				var cell = new THREE.Mesh(cellGeom, cellMat);
				cell.position.set(
					rackX - rackWidth * 0.5 + cellSpacingX * (x + 1),
					cellSpacingY * (y + 1),
					0
				);
				scene.add(cell);
			}
		}

		// Second rack on other side
		var rack2 = rack.clone();
		rack2.position.x = -rackX;
		scene.add(rack2);

		for (var y = 0; y < cellsPerColumn; y++) {
			for (var x = 0; x < cellsPerRow; x++) {
				var cellGeom = new THREE.SphereGeometry(cellRadius, 8, 8);
				var cellMat = new THREE.MeshStandardMaterial({
					color: 0xff0066,
					emissive: 0xaa0033
				});
				var cell = new THREE.Mesh(cellGeom, cellMat);
				cell.position.set(
					-rackX + rackWidth * 0.5 - cellSpacingX * (x + 1),
					cellSpacingY * (y + 1),
					0
				);
				scene.add(cell);
			}
		}
	};

	var createLaunchTubes = function() {
		var tubeRadius = 1.2;
		var tubeHeight = 20;
		var tubesPerSide = 4;
		var spacing = 3;
		var centerZ = -15;

		for (var i = 0; i < tubesPerSide; i++) {
			var xPos = -spacing * 1.5 + (i * spacing);

			// Tube
			var tubeGeom = new THREE.CylinderGeometry(tubeRadius, tubeRadius, tubeHeight, 8);
			var tubeMat = new THREE.MeshStandardMaterial({
				color: 0x333333,
				metalness: 0.9,
				roughness: 0.1
			});
			var tube = new THREE.Mesh(tubeGeom, tubeMat);
			tube.position.set(xPos, tubeHeight * 0.5, centerZ);
			scene.add(tube);

			// Launch glow base (emissive cylinder)
			var glowGeom = new THREE.CylinderGeometry(tubeRadius, tubeRadius, 2, 8);
			var glowMat = new THREE.MeshStandardMaterial({
				color: 0x0088ff,
				emissive: 0x0066ff
			});
			var glow = new THREE.Mesh(glowGeom, glowMat);
			glow.position.set(xPos, 1, centerZ);
			scene.add(glow);

			launchTubes.push(glow);
		}
	};

	var createPatrolDrones = function() {
		var droneCount = 6;
		var radius = 15;
		var height = 12;

		for (var i = 0; i < droneCount; i++) {
			var angle = (i / droneCount) * Math.PI * 2;

			// Create drone group
			var droneGroup = new THREE.Group();

			// Body
			var bodyGeom = new THREE.BoxGeometry(2, 1.5, 3);
			var bodyMat = new THREE.MeshStandardMaterial({
				color: 0xff3300,
				metalness: 0.8
			});
			var body = new THREE.Mesh(bodyGeom, bodyMat);
			droneGroup.add(body);

			// Rotor arms
			for (var j = -1; j <= 1; j += 2) {
				var armGeom = new THREE.CylinderGeometry(0.15, 0.15, 3, 8);
				var armMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
				var arm = new THREE.Mesh(armGeom, armMat);
				arm.position.set(j * 1.2, 0.5, 0);
				arm.rotation.z = Math.PI * 0.5;
				droneGroup.add(arm);

				// Spinning rotors
				var rotorGeom = new THREE.SphereGeometry(0.25, 8, 8);
				var rotorMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
				var rotor = new THREE.Mesh(rotorGeom, rotorMat);
				rotor.position.set(j * 1.5, 0.5, 0);
				droneGroup.add(rotor);
			}

			// Camera
			var cameraGeom = new THREE.ConeGeometry(0.4, 0.8, 8);
			var cameraMat = new THREE.MeshStandardMaterial({ color: 0x0099ff });
			var camera = new THREE.Mesh(cameraGeom, cameraMat);
			camera.position.set(0, -0.3, 1.8);
			camera.rotation.x = Math.PI * 0.5;
			droneGroup.add(camera);

			droneGroup.position.set(
				Math.cos(angle) * radius,
				height,
				Math.sin(angle) * radius
			);

			scene.add(droneGroup);

			patrolDrones.push({
				group: droneGroup,
				angle: angle,
				radius: radius,
				height: height,
				speed: 0.3 + (i * 0.05)
			});
		}
	};

	var createControlConsole = function() {
		// Central island
		var islandGeom = new THREE.BoxGeometry(8, 2, 6);
		var islandMat = new THREE.MeshStandardMaterial({ color: 0x444444, metalness: 0.5 });
		var island = new THREE.Mesh(islandGeom, islandMat);
		island.position.set(0, 1, 10);
		scene.add(island);

		// Console screens
		var screenGeom = new THREE.BoxGeometry(3, 2, 0.2);
		var screenMat = new THREE.MeshStandardMaterial({
			color: 0x001111,
			emissive: 0x00aa00
		});

		for (var i = 0; i < 3; i++) {
			var screen = new THREE.Mesh(screenGeom, screenMat);
			screen.position.set(
				-3 + (i * 3),
				3.5,
				10
			);
			scene.add(screen);
		}

		// Control panels on sides
		var panelGeom = new THREE.BoxGeometry(2, 2, 0.3);
		var panelMat = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.7 });

		var leftPanel = new THREE.Mesh(panelGeom, panelMat);
		leftPanel.position.set(-4.5, 2.5, 10);
		leftPanel.rotation.y = Math.PI * 0.25;
		scene.add(leftPanel);

		var rightPanel = new THREE.Mesh(panelGeom, panelMat);
		rightPanel.position.set(4.5, 2.5, 10);
		rightPanel.rotation.y = -Math.PI * 0.25;
		scene.add(rightPanel);

		// Joystick control
		var stickBaseGeom = new THREE.CylinderGeometry(0.4, 0.5, 0.3, 8);
		var stickBaseMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
		var stickBase = new THREE.Mesh(stickBaseGeom, stickBaseMat);
		stickBase.position.set(0, 2.5, 8);
		scene.add(stickBase);

		var stickGeom = new THREE.CylinderGeometry(0.1, 0.1, 1.5, 6);
		var stickMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
		var stick = new THREE.Mesh(stickGeom, stickMat);
		stick.position.set(0, 3.2, 8);
		scene.add(stick);
	};

	var createStorageArea = function() {
		var shelfX = -20;
		var shelfY = 8;
		var shelfZ = 15;
		var shelfWidth = 15;
		var shelfHeight = 3;

		// Shelving structure
		var backGeom = new THREE.BoxGeometry(shelfWidth, shelfHeight, 1);
		var backMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
		var back = new THREE.Mesh(backGeom, backMat);
		back.position.set(shelfX, shelfY, shelfZ);
		scene.add(back);

		// Component boxes on shelves
		var boxSize = 1;
		var boxSpacingX = 2;
		var boxSpacingY = 1.5;

		for (var y = 0; y < 2; y++) {
			for (var x = 0; x < 5; x++) {
				var boxGeom = new THREE.BoxGeometry(boxSize, boxSize, boxSize);
				var boxMat = new THREE.MeshStandardMaterial({
					color: 0xff6600 + (Math.random() * 0x330000 | 0)
				});
				var box = new THREE.Mesh(boxGeom, boxMat);
				box.position.set(
					shelfX - shelfWidth * 0.25 + (x * boxSpacingX),
					1 + y * boxSpacingY,
					shelfZ
				);
				scene.add(box);
			}
		}

		// Drone frames
		for (var i = 0; i < 3; i++) {
			createPartialDrone(
				shelfX + 5,
				2.5 + (i * 2),
				shelfZ,
				0
			);
		}
	};

	var createTestingRange = function() {
		var rangeX = 20;
		var rangeZ = 15;
		var rangeLength = 20;
		var rangeWidth = 15;

		// Open floor area with grid markings
		var floorGeom = new THREE.BoxGeometry(rangeLength, 0.1, rangeWidth);
		var floorMat = new THREE.MeshStandardMaterial({
			color: 0x555555,
			metalness: 0.3
		});
		var floor = new THREE.Mesh(floorGeom, floorMat);
		floor.position.set(rangeX, 0.05, rangeZ);
		scene.add(floor);

		// Target dummies on poles
		var targetCount = 6;
		var targetSpacing = 4;

		for (var i = 0; i < targetCount; i++) {
			var targetZ = rangeZ - 6 + (i * targetSpacing);

			// Pole
			var poleGeom = new THREE.CylinderGeometry(0.2, 0.2, 3, 6);
			var poleMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
			var pole = new THREE.Mesh(poleGeom, poleMat);
			pole.position.set(rangeX, 1.5, targetZ);
			scene.add(pole);

			// Target dummy (BoxGeometry torso + head)
			var torsoGeom = new THREE.BoxGeometry(1, 1.5, 0.5);
			var torsoMat = new THREE.MeshStandardMaterial({ color: 0xff3333 });
			var torso = new THREE.Mesh(torsoGeom, torsoMat);
			torso.position.set(rangeX, 2.5, targetZ);
			scene.add(torso);

			var headGeom = new THREE.BoxGeometry(0.5, 0.6, 0.5);
			var headMat = new THREE.MeshStandardMaterial({ color: 0xffaa00 });
			var head = new THREE.Mesh(headGeom, headMat);
			head.position.set(rangeX, 3.5, targetZ);
			scene.add(head);
		}
	};

	var createCrashBay = function() {
		var bayX = -30;
		var bayZ = -15;

		// Bay floor area
		var bayFloorGeom = new THREE.BoxGeometry(12, 0.2, 10);
		var bayFloorMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
		var bayFloor = new THREE.Mesh(bayFloorGeom, bayFloorMat);
		bayFloor.position.set(bayX, 0.1, bayZ);
		scene.add(bayFloor);

		// Damaged drone parts scattered
		for (var i = 0; i < 5; i++) {
			var partGeom = new THREE.BoxGeometry(1.5, 0.8, 1);
			var partMat = new THREE.MeshStandardMaterial({
				color: 0x663300,
				metalness: 0.4
			});
			var part = new THREE.Mesh(partGeom, partMat);
			part.position.set(
				bayX - 4 + (Math.random() * 6),
				0.5,
				bayZ - 3 + (Math.random() * 4)
			);
			part.rotation.set(
				Math.random() * Math.PI * 0.5,
				Math.random() * Math.PI,
				Math.random() * Math.PI * 0.3
			);
			scene.add(part);
		}

		// Repair equipment (tall cylindrical equipment)
		var equipGeom = new THREE.CylinderGeometry(0.5, 0.6, 3, 8);
		var equipMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
		var equip = new THREE.Mesh(equipGeom, equipMat);
		equip.position.set(bayX + 3, 1.5, bayZ);
		scene.add(equip);
	};

	var createEMPShields = function() {
		var corners = [
			{ x: 35, z: 35 },
			{ x: -35, z: 35 },
			{ x: 35, z: -35 },
			{ x: -35, z: -35 }
		];

		for (var c = 0; c < corners.length; c++) {
			var corner = corners[c];

			// Cylindrical pylon
			var pylonGeom = new THREE.CylinderGeometry(1, 1.5, 10, 8);
			var pylonMat = new THREE.MeshStandardMaterial({
				color: 0x0066ff,
				emissive: 0x003399,
				metalness: 0.8
			});
			var pylon = new THREE.Mesh(pylonGeom, pylonMat);
			pylon.position.set(corner.x, 5, corner.z);
			scene.add(pylon);

			// EMP arc effect (LineSegments)
			var arcPoints = [];
			var arcSegments = 12;
			var arcHeight = 8;

			for (var i = 0; i <= arcSegments; i++) {
				var t = i / arcSegments;
				var x = corner.x + Math.sin(t * Math.PI) * 6;
				var y = 3 + (t * arcHeight);
				var z = corner.z;
				arcPoints.push(new THREE.Vector3(x, y, z));
			}

			var arcGeom = new THREE.BufferGeometry().setFromPoints(arcPoints);
			var arcMat = new THREE.LineBasicMaterial({
				color: 0x00ffff,
				linewidth: 2
			});
			var arcLine = new THREE.LineSegments(arcGeom, arcMat);
			scene.add(arcLine);

			empArcs.push({
				line: arcLine,
				pulsePhase: (c * Math.PI * 0.5)
			});
		}
	};

	var createAirlockDoors = function() {
		var doorPositions = [
			{ x: 30, z: 25, dir: 0 },
			{ x: -30, z: 25, dir: 1 }
		];

		for (var i = 0; i < doorPositions.length; i++) {
			var pos = doorPositions[i];
			var isRight = pos.dir === 1;

			// Door frame
			var frameGeom = new THREE.BoxGeometry(3, 4, 0.3);
			var frameMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
			var frame = new THREE.Mesh(frameGeom, frameMat);
			frame.position.set(pos.x, 2, pos.z);
			scene.add(frame);

			// Sliding door panel
			var panelGeom = new THREE.BoxGeometry(3, 4, 0.2);
			var panelMat = new THREE.MeshStandardMaterial({
				color: 0x444444,
				metalness: 0.7
			});
			var panel = new THREE.Mesh(panelGeom, panelMat);
			panel.position.set(pos.x, 2, pos.z);
			scene.add(panel);

			airlockDoors.push({
				panel: panel,
				baseZ: pos.z,
				isOpen: false,
				openSpeed: 1.5,
				maxOpen: 2
			});
		}
	};

	var createFloor = function() {
		var floorGeom = new THREE.BoxGeometry(80, 0.5, 80);
		var floorMat = new THREE.MeshStandardMaterial({
			color: 0x2a2a2a,
			metalness: 0.2,
			roughness: 0.8
		});
		var floor = new THREE.Mesh(floorGeom, floorMat);
		floor.position.set(0, -0.25, 0);
		scene.add(floor);
	};

	var createWalls = function() {
		var wallHeight = 15;
		var wallThickness = 1;
		var extent = 40;

		// Back wall
		var backGeom = new THREE.BoxGeometry(100, wallHeight, wallThickness);
		var wallMat = new THREE.MeshStandardMaterial({
			color: 0x1a1a1a,
			metalness: 0.3
		});
		var backWall = new THREE.Mesh(backGeom, wallMat);
		backWall.position.set(0, wallHeight * 0.5, -extent);
		scene.add(backWall);

		// Front wall
		var frontWall = new THREE.Mesh(backGeom, wallMat);
		frontWall.position.set(0, wallHeight * 0.5, extent);
		scene.add(frontWall);

		// Side walls
		var sideGeom = new THREE.BoxGeometry(wallThickness, wallHeight, 100);

		var leftWall = new THREE.Mesh(sideGeom, wallMat);
		leftWall.position.set(-extent, wallHeight * 0.5, 0);
		scene.add(leftWall);

		var rightWall = new THREE.Mesh(sideGeom, wallMat);
		rightWall.position.set(extent, wallHeight * 0.5, 0);
		scene.add(rightWall);
	};

	var createLighting = function() {
		// Ambient light
		var ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
		scene.add(ambientLight);

		// Directional light (sun-like)
		var dirLight = new THREE.DirectionalLight(0xffffff, 0.6);
		dirLight.position.set(20, 25, 20);
		dirLight.castShadow = true;
		scene.add(dirLight);

		// Point lights near control console
		var consoleLight = new THREE.PointLight(0x00ff00, 1, 20);
		consoleLight.position.set(0, 4, 10);
		scene.add(consoleLight);

		// Blue glow from launch tubes
		var launchLight = new THREE.PointLight(0x0088ff, 0.8, 25);
		launchLight.position.set(0, 3, -15);
		scene.add(launchLight);
	};

	var update = function(delta) {
		time += delta;

		// Update patrol drones
		for (var i = 0; i < patrolDrones.length; i++) {
			var drone = patrolDrones[i];
			drone.angle += drone.speed * delta * 0.5;
			drone.group.position.x = Math.cos(drone.angle) * drone.radius;
			drone.group.position.z = Math.sin(drone.angle) * drone.radius;
			drone.group.rotation.z += delta * 2;
		}

		// Update assembly conveyor movement
		for (var i = 0; i < assemblyConveyors.length; i++) {
			var conveyor = assemblyConveyors[i];
			conveyor.offset += conveyor.speed * delta;
			if (conveyor.offset > 1) {
				conveyor.offset -= 1;
			}
		}

		// Update launch tube glow
		for (var i = 0; i < launchTubes.length; i++) {
			var tube = launchTubes[i];
			var glow = 0.5 + Math.sin(time * 3 + i) * 0.3;
			tube.material.emissiveIntensity = glow;
		}

		// Update EMP arc pulses
		for (var i = 0; i < empArcs.length; i++) {
			var emp = empArcs[i];
			var pulse = Math.sin(time * 2 + emp.pulsePhase) * 0.5 + 0.5;
			emp.line.material.opacity = pulse;
		}

		// Update airlock doors (animated open/close)
		for (var i = 0; i < airlockDoors.length; i++) {
			var door = airlockDoors[i];
			var targetOpen = (time * 0.5) % 2 < 1;

			if (targetOpen && !door.isOpen) {
				door.isOpen = true;
			} else if (!targetOpen && door.isOpen) {
				door.isOpen = false;
			}

			var currentZ = door.panel.position.z;
			var targetZ = door.baseZ + (door.isOpen ? door.maxOpen : 0);
			var diff = targetZ - currentZ;

			if (Math.abs(diff) > 0.01) {
				door.panel.position.z += diff * Math.min(door.openSpeed * delta, 1);
			}
		}
	};

	var reset = function() {
		time = 0;
		for (var i = 0; i < patrolDrones.length; i++) {
			patrolDrones[i].angle = (i / patrolDrones.length) * Math.PI * 2;
		}
		for (var i = 0; i < airlockDoors.length; i++) {
			airlockDoors[i].isOpen = false;
			airlockDoors[i].panel.position.z = airlockDoors[i].baseZ;
		}
	};

	return {
		init: init,
		update: update,
		reset: reset
	};
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail drone-bay.js",_e&&_e.message); }
/* === deep-bunker.js === */
try {
;
window.DeepBunker = (function() {
	'use strict';

	var sceneRef = null;
	var cameraRef = null;
	var bunkerMeshes = [];
	var generatorPistons = [];
	var emergencyLights = [];
	var globalTime = 0;

	function addMesh(mesh) {
		bunkerMeshes.push(mesh);
		if (sceneRef) sceneRef.add(mesh);
	}

	function buildWalls() {
		var concreteMat = new THREE.MeshStandardMaterial({
			color: 0x404040,
			metalness: 0.1,
			roughness: 0.8
		});

		var wallGeom = new THREE.BoxGeometry(40, 15, 80);
		var leftWall = new THREE.Mesh(wallGeom, concreteMat);
		leftWall.position.set(-20, 0, 0);
		addMesh(leftWall);

		var rightWall = new THREE.Mesh(wallGeom, concreteMat);
		rightWall.position.set(20, 0, 0);
		addMesh(rightWall);

		var ceilingGeom = new THREE.BoxGeometry(40, 2, 80);
		var ceiling = new THREE.Mesh(ceilingGeom, concreteMat);
		ceiling.position.set(0, 15, 0);
		addMesh(ceiling);

		var floorGeom = new THREE.BoxGeometry(40, 1, 80);
		var floor = new THREE.Mesh(floorGeom, concreteMat);
		floor.position.set(0, -8, 0);
		addMesh(floor);
	}

	function buildPillars() {
		var pillarMat = new THREE.MeshStandardMaterial({
			color: 0x555555,
			metalness: 0.05,
			roughness: 0.85
		});

		var positions = [
			[-10, 0, -20], [-10, 0, 0], [-10, 0, 20],
			[10, 0, -20], [10, 0, 0], [10, 0, 20]
		];

		var i = 0;
		while (i < positions.length) {
			var pillarGeom = new THREE.CylinderGeometry(1.5, 1.5, 20, 8);
			var pillar = new THREE.Mesh(pillarGeom, pillarMat);
			pillar.position.set(positions[i][0], positions[i][1], positions[i][2]);
			addMesh(pillar);
			i = i + 1;
		}
	}

	function buildBlastDoors() {
		var steelMat = new THREE.MeshStandardMaterial({
			color: 0x2a2a2a,
			metalness: 0.9,
			roughness: 0.2
		});

		var doorGeom = new THREE.BoxGeometry(8, 12, 0.8);
		var frontDoor = new THREE.Mesh(doorGeom, steelMat);
		frontDoor.position.set(0, 0, -35);
		addMesh(frontDoor);

		var rearDoor = new THREE.Mesh(doorGeom, steelMat);
		rearDoor.position.set(0, 0, 35);
		addMesh(rearDoor);

		var lockGeom = new THREE.SphereGeometry(0.4, 16, 16);
		var lockMat = new THREE.MeshStandardMaterial({
			color: 0xffaa00,
			metalness: 0.95,
			roughness: 0.1
		});

		var frontLock = new THREE.Mesh(lockGeom, lockMat);
		frontLock.position.set(-2, 0, -35.5);
		addMesh(frontLock);

		var rearLock = new THREE.Mesh(lockGeom, lockMat);
		rearLock.position.set(2, 0, 35.5);
		addMesh(rearLock);
	}

	function buildGenerator() {
		var engineMat = new THREE.MeshStandardMaterial({
			color: 0x1a1a1a,
			metalness: 0.6,
			roughness: 0.3
		});

		var bodyGeom = new THREE.CylinderGeometry(2.5, 2.5, 6, 16);
		var body = new THREE.Mesh(bodyGeom, engineMat);
		body.position.set(-15, -2, 30);
		addMesh(body);

		var pistonPositions = [
			[-2, -2, 30], [0, -2, 30], [2, -2, 30]
		];

		var j = 0;
		while (j < pistonPositions.length) {
			var pistonGeom = new THREE.CylinderGeometry(0.6, 0.6, 4, 8);
			var pistonMat = new THREE.MeshStandardMaterial({
				color: 0x888888,
				metalness: 0.7,
				roughness: 0.2
			});
			var piston = new THREE.Mesh(pistonGeom, pistonMat);
			piston.position.set(pistonPositions[j][0], pistonPositions[j][1], pistonPositions[j][2]);
			piston.userData = {
				baseY: pistonPositions[j][1],
				offset: pistonPositions[j][0] * 0.5
			};
			generatorPistons.push(piston);
			addMesh(piston);
			j = j + 1;
		}
	}

	function buildOperationsRoom() {
		var tableMat = new THREE.MeshStandardMaterial({
			color: 0x3a3a3a,
			metalness: 0.3,
			roughness: 0.6
		});

		var tableGeom = new THREE.BoxGeometry(12, 1, 8);
		var mapTable = new THREE.Mesh(tableGeom, tableMat);
		mapTable.position.set(0, 2, 0);
		addMesh(mapTable);

		var chairGeom = new THREE.BoxGeometry(1, 2, 1);
		var chairMat = new THREE.MeshStandardMaterial({
			color: 0x4a4a4a,
			metalness: 0.2,
			roughness: 0.7
		});

		var chairPositions = [
			[-4, 1, 5], [0, 1, 5], [4, 1, 5], [-6, 1, 0], [6, 1, 0]
		];

		var k = 0;
		while (k < chairPositions.length) {
			var chair = new THREE.Mesh(chairGeom, chairMat);
			chair.position.set(chairPositions[k][0], chairPositions[k][1], chairPositions[k][2]);
			addMesh(chair);
			k = k + 1;
		}
	}

	function buildSleepingQuarters() {
		var frameMat = new THREE.MeshStandardMaterial({
			color: 0x8b7355,
			metalness: 0.4,
			roughness: 0.6
		});

		var bunkPositions = [
			[-12, 0, -15], [-12, 5, -15],
			[-12, 0, -8], [-12, 5, -8],
			[12, 0, -15], [12, 5, -15],
			[12, 0, -8], [12, 5, -8]
		];

		var m = 0;
		while (m < bunkPositions.length) {
			var bunkGeom = new THREE.BoxGeometry(3, 2, 2);
			var bunk = new THREE.Mesh(bunkGeom, frameMat);
			bunk.position.set(bunkPositions[m][0], bunkPositions[m][1], bunkPositions[m][2]);
			addMesh(bunk);
			m = m + 1;
		}
	}

	function buildEmergencyLights() {
		var lightMat = new THREE.MeshStandardMaterial({
			color: 0x333333,
			emissive: 0xff4400,
			emissiveIntensity: 0.5,
			metalness: 0.8,
			roughness: 0.1
		});

		var lightPositions = [
			[-15, 13, -25], [15, 13, -25],
			[-15, 13, 0], [15, 13, 0],
			[-15, 13, 25], [15, 13, 25]
		];

		var n = 0;
		while (n < lightPositions.length) {
			var bulbGeom = new THREE.SphereGeometry(0.5, 8, 8);
			var bulb = new THREE.Mesh(bulbGeom, lightMat);
			bulb.position.set(lightPositions[n][0], lightPositions[n][1], lightPositions[n][2]);
			emergencyLights.push(bulb);
			addMesh(bulb);

			var pointLight = new THREE.PointLight(0xff4400, 1, 20);
			pointLight.position.set(lightPositions[n][0], lightPositions[n][1], lightPositions[n][2]);
			emergencyLights.push(pointLight);
			if (sceneRef) sceneRef.add(pointLight);
			n = n + 1;
		}
	}

	function buildElevatorShaft() {
		var shaftMat = new THREE.MeshStandardMaterial({
			color: 0x2a2a2a,
			metalness: 0.5,
			roughness: 0.4
		});

		var shaftGeom = new THREE.CylinderGeometry(3, 3, 100, 12);
		var shaft = new THREE.Mesh(shaftGeom, shaftMat);
		shaft.position.set(0, -20, 0);
		addMesh(shaft);

		var cabinetGeom = new THREE.BoxGeometry(2, 6, 2);
		var cabinet = new THREE.Mesh(cabinetGeom, shaftMat);
		cabinet.position.set(0, 5, 0);
		addMesh(cabinet);
	}

	function init(scene, camera) {
		sceneRef = scene;
		cameraRef = camera;
		bunkerMeshes = [];
		generatorPistons = [];
		emergencyLights = [];
		globalTime = 0;

		buildWalls();
		buildPillars();
		buildBlastDoors();
		buildOperationsRoom();
		buildSleepingQuarters();
		buildGenerator();
		buildEmergencyLights();
		buildElevatorShaft();
	}

	function update(delta) {
		globalTime = globalTime + delta;

		var pIdx = 0;
		while (pIdx < generatorPistons.length) {
			var wobble = Math.sin(globalTime * 8 + generatorPistons[pIdx].userData.offset) * 0.8;
			generatorPistons[pIdx].position.y = generatorPistons[pIdx].userData.baseY + wobble;
			pIdx = pIdx + 1;
		}

		var lIdx = 0;
		while (lIdx < emergencyLights.length) {
			var item = emergencyLights[lIdx];
			if (item.isLight) {
				var flicker = 0.3 + Math.sin(globalTime * 3 + lIdx * 0.5) * 0.2 + Math.random() * 0.3;
				item.intensity = Math.max(0.1, flicker);
			}
			lIdx = lIdx + 1;
		}
	}

	function reset() {
		var i = 0;
		while (i < bunkerMeshes.length) {
			if (sceneRef) sceneRef.remove(bunkerMeshes[i]);
			i = i + 1;
		}

		var j = 0;
		while (j < emergencyLights.length) {
			var item = emergencyLights[j];
			if (item.isLight && sceneRef) sceneRef.remove(item);
			j = j + 1;
		}

		bunkerMeshes = [];
		generatorPistons = [];
		emergencyLights = [];
		globalTime = 0;
	}

	return {
		init: init,
		update: update,
		reset: reset
	};
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail deep-bunker.js",_e&&_e.message); }
/* === mine-cart.js === */
try {
;
window.MineCart = (function() {
  'use strict';

  var scene = null;
  var camera = null;
  var carts = [];
  var crusher = null;
  var crusherDrum = null;
  var lanterns = [];
  var waterBody = null;
  var canaryBird = null;
  var canary = null;
  var canyonTime = 0;
  var cartTracks = [];
  var gemVeins = [];

  var init = function(initScene, initCamera) {
    scene = initScene;
    camera = initCamera;
    carts = [];
    lanterns = [];
    gemVeins = [];
    canyonTime = 0;

    scene.background = new THREE.Color(0x1a1a2e);
    scene.fog = new THREE.Fog(0x1a1a2e, 150, 300);

    buildMineTracks();
    buildMineCarts();
    buildSupportBeams();
    buildExplosivesStorage();
    buildCaveInSection();
    buildUndergroundLake();
    buildGemVeins();
    buildOreProcessing();
    buildHeadlamps();
    buildDynamiteCharges();
    buildCanaryCage();

    var ambientLight = new THREE.AmbientLight(0x3d3d5c, 0.4);
    scene.add(ambientLight);

    var pointLight1 = new THREE.PointLight(0xffaa00, 1.5, 80);
    pointLight1.position.set(20, 25, 0);
    scene.add(pointLight1);

    var pointLight2 = new THREE.PointLight(0x6666ff, 1, 60);
    pointLight2.position.set(-30, 20, 40);
    scene.add(pointLight2);
  };

  var buildMineTracks = function() {
    var trackMaterial = new THREE.LineBasicMaterial({ color: 0x8b7355, linewidth: 2 });

    var mainTrack = new THREE.Geometry();
    mainTrack.vertices.push(new THREE.Vector3(-80, 5, -40));
    mainTrack.vertices.push(new THREE.Vector3(-40, 5, -20));
    mainTrack.vertices.push(new THREE.Vector3(0, 5, 0));
    mainTrack.vertices.push(new THREE.Vector3(40, 5, 20));
    mainTrack.vertices.push(new THREE.Vector3(80, 5, 60));

    var leftRail = new THREE.LineSegments(mainTrack, trackMaterial);
    leftRail.position.x = -3;
    scene.add(leftRail);
    cartTracks.push(mainTrack.vertices);

    var rightRail = new THREE.LineSegments(mainTrack, trackMaterial);
    rightRail.position.x = 3;
    scene.add(rightRail);

    var junctionTrack = new THREE.Geometry();
    junctionTrack.vertices.push(new THREE.Vector3(0, 5, 0));
    junctionTrack.vertices.push(new THREE.Vector3(0, 5, 50));
    junctionTrack.vertices.push(new THREE.Vector3(-50, 5, 80));

    var junctionLeft = new THREE.LineSegments(junctionTrack, trackMaterial);
    junctionLeft.position.x = -3;
    scene.add(junctionLeft);

    var junctionRight = new THREE.LineSegments(junctionTrack, trackMaterial);
    junctionRight.position.x = 3;
    scene.add(junctionRight);

    var verticalTrack = new THREE.Geometry();
    verticalTrack.vertices.push(new THREE.Vector3(60, 5, 40));
    verticalTrack.vertices.push(new THREE.Vector3(60, 40, 40));

    var verticalLeft = new THREE.LineSegments(verticalTrack, trackMaterial);
    verticalLeft.position.x = -3;
    scene.add(verticalLeft);

    var verticalRight = new THREE.LineSegments(verticalTrack, trackMaterial);
    verticalRight.position.x = 3;
    scene.add(verticalRight);
  };

  var buildMineCarts = function() {
    var cartPositions = [
      { x: -70, y: 7, z: -35, speed: 0.02, trackIndex: 0 },
      { x: 20, y: 7, z: 10, speed: 0.015, trackIndex: 0 },
      { x: 50, y: 7, z: 40, speed: 0.025, trackIndex: 0 }
    ];

    cartPositions.forEach(function(cartPos) {
      var cartGroup = new THREE.Group();

      var cartBody = new THREE.Mesh(
        new THREE.BoxGeometry(8, 6, 14),
        new THREE.MeshStandardMaterial({ color: 0xff6b35, metalness: 0.3, roughness: 0.7 })
      );
      cartBody.position.y = 3;
      cartGroup.add(cartBody);

      var wheelFront = new THREE.Mesh(
        new THREE.CylinderGeometry(3, 3, 2, 16),
        new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.8, roughness: 0.2 })
      );
      wheelFront.rotation.z = Math.PI / 2;
      wheelFront.position.set(0, 2, 5);
      cartGroup.add(wheelFront);

      var wheelBack = new THREE.Mesh(
        new THREE.CylinderGeometry(3, 3, 2, 16),
        new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.8, roughness: 0.2 })
      );
      wheelBack.rotation.z = Math.PI / 2;
      wheelBack.position.set(0, 2, -5);
      cartGroup.add(wheelBack);

      var sideLeft = new THREE.Mesh(
        new THREE.BoxGeometry(1, 8, 14),
        new THREE.MeshStandardMaterial({ color: 0xff6b35, metalness: 0.2 })
      );
      sideLeft.position.set(-4, 4, 0);
      cartGroup.add(sideLeft);

      var sideRight = new THREE.Mesh(
        new THREE.BoxGeometry(1, 8, 14),
        new THREE.MeshStandardMaterial({ color: 0xff6b35, metalness: 0.2 })
      );
      sideRight.position.set(4, 4, 0);
      cartGroup.add(sideRight);

      cartGroup.position.set(cartPos.x, cartPos.y, cartPos.z);
      scene.add(cartGroup);

      carts.push({
        group: cartGroup,
        speed: cartPos.speed,
        progress: 0,
        wheelFront: wheelFront,
        wheelBack: wheelBack
      });
    });
  };

  var buildSupportBeams = function() {
    var beamMaterial = new THREE.MeshStandardMaterial({ color: 0x8b4513, roughness: 0.8 });

    var zPositions = [-40, -20, 0, 20, 40, 60];
    zPositions.forEach(function(z) {
      var verticalBeam = new THREE.Mesh(
        new THREE.BoxGeometry(2, 45, 2),
        beamMaterial
      );
      verticalBeam.position.set(-50, 22.5, z);
      scene.add(verticalBeam);

      var verticalBeam2 = new THREE.Mesh(
        new THREE.BoxGeometry(2, 45, 2),
        beamMaterial
      );
      verticalBeam2.position.set(50, 22.5, z);
      scene.add(verticalBeam2);

      var horizontalBeam = new THREE.Mesh(
        new THREE.BoxGeometry(100, 2, 2),
        beamMaterial
      );
      horizontalBeam.position.set(0, 45, z);
      scene.add(horizontalBeam);
    });

    for (var i = -60; i <= 60; i += 10) {
      var crossBeam1 = new THREE.Mesh(
        new THREE.BoxGeometry(2, 2, 50),
        beamMaterial
      );
      crossBeam1.position.set(i, 30, 0);
      scene.add(crossBeam1);

      var crossBeam2 = new THREE.Mesh(
        new THREE.BoxGeometry(2, 2, 50),
        beamMaterial
      );
      crossBeam2.position.set(i, 15, 0);
      scene.add(crossBeam2);
    }
  };

  var buildExplosivesStorage = function() {
    var cratesMaterial = new THREE.MeshStandardMaterial({ color: 0x8b0000, roughness: 0.6 });
    var plungerMaterial = new THREE.MeshStandardMaterial({ color: 0xffff00, metalness: 0.9 });

    for (var x = -35; x <= -15; x += 10) {
      for (var z = -50; z <= -30; z += 10) {
        var crate = new THREE.Mesh(
          new THREE.BoxGeometry(8, 8, 8),
          cratesMaterial
        );
        crate.position.set(x, 12, z);
        scene.add(crate);

        var plunger = new THREE.Mesh(
          new THREE.CylinderGeometry(0.8, 0.8, 3, 8),
          plungerMaterial
        );
        plunger.position.set(x, 16, z);
        scene.add(plunger);

        var detonator = new THREE.Mesh(
          new THREE.SphereGeometry(0.4, 8, 8),
          new THREE.MeshStandardMaterial({ color: 0xff6600, emissive: 0xff3300 })
        );
        detonator.position.set(x, 18.5, z);
        scene.add(detonator);
      }
    }
  };

  var buildCaveInSection = function() {
    var rockMaterial = new THREE.MeshStandardMaterial({ color: 0x5a5a5a, roughness: 0.9 });

    var cavePosition = { x: 25, y: 0, z: 45 };

    for (var i = 0; i < 12; i++) {
      var rockSize = 8 + Math.random() * 8;
      var rock = new THREE.Mesh(
        new THREE.BoxGeometry(rockSize, rockSize * 0.7, rockSize * 0.8),
        rockMaterial
      );
      rock.position.set(
        cavePosition.x + (Math.random() - 0.5) * 30,
        cavePosition.y + rockSize * 0.35,
        cavePosition.z + (Math.random() - 0.5) * 20
      );
      rock.rotation.set(
        Math.random() * Math.PI * 0.5,
        Math.random() * Math.PI,
        Math.random() * Math.PI * 0.3
      );
      scene.add(rock);
    }

    var dustCloud = new THREE.Mesh(
      new THREE.SphereGeometry(25, 16, 16),
      new THREE.MeshStandardMaterial({ color: 0x9a9a9a, transparent: true, opacity: 0.15 })
    );
    dustCloud.position.set(cavePosition.x, cavePosition.y + 15, cavePosition.z);
    scene.add(dustCloud);
  };

  var buildUndergroundLake = function() {
    var lakeX = 70;
    var lakeY = 0;
    var lakeZ = -60;

    var waterGeometry = new THREE.BoxGeometry(40, 25, 50);
    waterBody = new THREE.Mesh(
      waterGeometry,
      new THREE.MeshStandardMaterial({
        color: 0x1e90ff,
        transparent: true,
        opacity: 0.6,
        metalness: 0.8,
        roughness: 0.1
      })
    );
    waterBody.position.set(lakeX, lakeY + 12.5, lakeZ);
    scene.add(waterBody);

    var lakeBeds = [];
    for (var i = 0; i < 8; i++) {
      var bedX = lakeX + (Math.random() - 0.5) * 35;
      var bedZ = lakeZ + (Math.random() - 0.5) * 45;
      var bed = new THREE.Mesh(
        new THREE.BoxGeometry(5 + Math.random() * 5, 2, 8),
        new THREE.MeshStandardMaterial({ color: 0x6b4423, roughness: 0.9 })
      );
      bed.position.set(bedX, 1, bedZ);
      scene.add(bed);
      lakeBeds.push(bed);
    }
  };

  var buildGemVeins = function() {
    var gemColors = [0xffff00, 0x0099ff, 0x9933ff];
    var wallPositions = [
      { x: -90, z: -30 },
      { x: -90, z: 30 },
      { x: 90, z: 0 },
      { x: 0, z: -90 },
      { x: 0, z: 90 }
    ];

    wallPositions.forEach(function(wallPos) {
      for (var i = 0; i < 5; i++) {
        var gemColor = gemColors[Math.floor(Math.random() * gemColors.length)];
        var gem = new THREE.Mesh(
          new THREE.ConeGeometry(2 + Math.random() * 2, 4 + Math.random() * 3, 6),
          new THREE.MeshStandardMaterial({
            color: gemColor,
            emissive: gemColor,
            emissiveIntensity: 0.4,
            metalness: 0.9,
            roughness: 0.2
          })
        );
        gem.position.set(
          wallPos.x + (Math.random() - 0.5) * 5,
          10 + Math.random() * 30,
          wallPos.z + (Math.random() - 0.5) * 5
        );
        gem.rotation.set(
          Math.random() * Math.PI,
          Math.random() * Math.PI,
          Math.random() * Math.PI
        );
        scene.add(gem);
        gemVeins.push(gem);
      }
    });
  };

  var buildOreProcessing = function() {
    var baseX = -60;
    var baseY = 8;
    var baseZ = 30;

    var base = new THREE.Mesh(
      new THREE.BoxGeometry(30, 4, 20),
      new THREE.MeshStandardMaterial({ color: 0x4a4a4a, roughness: 0.8 })
    );
    base.position.set(baseX, baseY, baseZ);
    scene.add(base);

    var frame1 = new THREE.Mesh(
      new THREE.BoxGeometry(3, 25, 3),
      new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.7 })
    );
    frame1.position.set(baseX - 12, baseY + 12.5, baseZ - 8);
    scene.add(frame1);

    var frame2 = new THREE.Mesh(
      new THREE.BoxGeometry(3, 25, 3),
      new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.7 })
    );
    frame2.position.set(baseX + 12, baseY + 12.5, baseZ - 8);
    scene.add(frame2);

    crusherDrum = new THREE.Mesh(
      new THREE.CylinderGeometry(6, 6, 18, 16),
      new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.9, roughness: 0.3 })
    );
    crusherDrum.rotation.z = Math.PI / 2;
    crusherDrum.position.set(baseX, baseY + 12, baseZ);
    scene.add(crusherDrum);

    var hopper = new THREE.Mesh(
      new THREE.BoxGeometry(22, 15, 16),
      new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.7 })
    );
    hopper.position.set(baseX, baseY + 22.5, baseZ);
    scene.add(hopper);

    crusher = {
      drum: crusherDrum,
      rotation: 0
    };
  };

  var buildHeadlamps = function() {
    var lampPositions = [];
    for (var x = -80; x <= 80; x += 20) {
      for (var z = -60; z <= 80; z += 15) {
        lampPositions.push({ x: x, z: z });
      }
    }

    lampPositions.forEach(function(pos) {
      var lampGroup = new THREE.Group();

      var lampBulb = new THREE.Mesh(
        new THREE.SphereGeometry(1.2, 8, 8),
        new THREE.MeshStandardMaterial({
          color: 0xffdd77,
          emissive: 0xffdd77,
          emissiveIntensity: 0.6
        })
      );
      lampGroup.add(lampBulb);

      var lampCage = new THREE.Mesh(
        new THREE.CylinderGeometry(1.5, 1.5, 2.5, 8),
        new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.8 })
      );
      lampCage.position.y = -1.5;
      lampGroup.add(lampCage);

      var lampBracket = new THREE.Mesh(
        new THREE.BoxGeometry(0.5, 3, 0.5),
        new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.7 })
      );
      lampBracket.position.set(0, -2.5, 0);
      lampGroup.add(lampBracket);

      lampGroup.position.set(pos.x, 42, pos.z);
      scene.add(lampGroup);

      lanterns.push({
        bulb: lampBulb,
        baseIntensity: 0.6,
        phase: Math.random() * Math.PI * 2
      });
    });
  };

  var buildDynamiteCharges = function() {
    var chargePositions = [
      { x: 15, y: 8, z: 35 },
      { x: -25, y: 10, z: 50 },
      { x: 45, y: 6, z: 15 },
      { x: -45, y: 12, z: -25 }
    ];

    chargePositions.forEach(function(pos) {
      for (var i = 0; i < 3; i++) {
        var stick = new THREE.Mesh(
          new THREE.CylinderGeometry(0.6, 0.6, 4, 8),
          new THREE.MeshStandardMaterial({ color: 0xff0000, roughness: 0.9 })
        );
        stick.position.set(pos.x + i * 1.5, pos.y, pos.z);
        scene.add(stick);

        var fuseStart = new THREE.Vector3(pos.x + i * 1.5, pos.y + 2, pos.z);
        var fuseEnd = new THREE.Vector3(pos.x + i * 1.5 + 3, pos.y + 5, pos.z);
        var fuseGeometry = new THREE.Geometry();
        fuseGeometry.vertices.push(fuseStart);
        fuseGeometry.vertices.push(fuseEnd);

        var fuse = new THREE.LineSegments(
          fuseGeometry,
          new THREE.LineBasicMaterial({ color: 0xffff00, linewidth: 1.5 })
        );
        scene.add(fuse);
      }
    });
  };

  var buildCanaryCage = function() {
    var cageX = -70;
    var cageY = 40;
    var cageZ = 50;

    var cageFrame = new THREE.Mesh(
      new THREE.CylinderGeometry(3, 3, 6, 12),
      new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.7 })
    );
    cageFrame.position.set(cageX, cageY, cageZ);
    scene.add(cageFrame);

    var cageBars = [];
    for (var i = 0; i < 8; i++) {
      var angle = (i / 8) * Math.PI * 2;
      var barX = cageX + Math.cos(angle) * 3;
      var barZ = cageZ + Math.sin(angle) * 3;

      var bar = new THREE.Mesh(
        new THREE.CylinderGeometry(0.2, 0.2, 6, 4),
        new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.8 })
      );
      bar.position.set(barX, cageY, barZ);
      scene.add(bar);
      cageBars.push(bar);
    }

    var cageBottom = new THREE.Mesh(
      new THREE.CylinderGeometry(2.8, 2.8, 0.4, 12),
      new THREE.MeshStandardMaterial({ color: 0x8b7355, roughness: 0.7 })
    );
    cageBottom.position.set(cageX, cageY - 3, cageZ);
    scene.add(cageBottom);

    canaryBird = new THREE.Mesh(
      new THREE.SphereGeometry(0.4, 6, 6),
      new THREE.MeshStandardMaterial({
        color: 0xffdd00,
        emissive: 0xffaa00,
        emissiveIntensity: 0.3
      })
    );
    canaryBird.position.set(cageX, cageY - 1, cageZ);
    scene.add(canaryBird);

    var wing = new THREE.Mesh(
      new THREE.SphereGeometry(0.2, 4, 4),
      new THREE.MeshStandardMaterial({ color: 0xffdd00 })
    );
    wing.scale.set(2, 0.5, 0.3);
    wing.position.set(cageX + 0.3, cageY - 0.9, cageZ);
    canaryBird.add(wing);

    canary = {
      bird: canaryBird,
      cageX: cageX,
      cageY: cageY,
      cageZ: cageZ,
      bouncePhase: 0
    };
  };

  var update = function(delta) {
    canyonTime += delta;

    carts.forEach(function(cart) {
      cart.progress += cart.speed * delta;
      if (cart.progress > 1) cart.progress = 0;

      var t = cart.progress;
      var x = -70 + (t * 150);
      var z = -35 + (t * 95);
      var y = 7 + Math.sin(t * Math.PI) * 3;

      cart.group.position.set(x, y, z);

      cart.wheelFront.rotation.x += 0.1;
      cart.wheelBack.rotation.x += 0.1;
    });

    if (crusher && crusherDrum) {
      crusher.rotation += 0.02;
      crusherDrum.rotation.z = crusher.rotation;
    }

    waterBody.position.y = 12.5 + Math.sin(canyonTime * 0.5) * 0.3;

    lanterns.forEach(function(lantern, index) {
      var flicker = lantern.baseIntensity + Math.sin(canyonTime * 3 + lantern.phase) * 0.15;
      lantern.bulb.material.emissiveIntensity = flicker;
    });

    gemVeins.forEach(function(gem) {
      gem.rotation.x += 0.005;
      gem.rotation.y += 0.008;
      var pulse = 0.3 + Math.sin(canyonTime * 2 + gem.position.x) * 0.2;
      gem.material.emissiveIntensity = pulse;
    });

    if (canary && canaryBird) {
      canary.bouncePhase += 0.05;
      canaryBird.position.y = canary.cageY - 1 + Math.sin(canary.bouncePhase) * 0.8;
      canaryBird.rotation.z = Math.sin(canary.bouncePhase * 0.5) * 0.3;
    }
  };

  var reset = function() {
    carts.forEach(function(cart) {
      cart.progress = 0;
      cart.group.position.set(-70, 7, -35);
    });
    canyonTime = 0;
    if (crusher) crusher.rotation = 0;
  };

  return {
    init: init,
    update: update,
    reset: reset
  };
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail mine-cart.js",_e&&_e.message); }
/* === water-tower-siege.js === */
try {
;
window.WaterTowerSiege = (function() {
  'use strict';

  var scene = null;
  var camera = null;
  var towers = [];
  var catwalks = [];
  var waterBlocks = [];
  var pipes = [];
  var fence = null;
  var burstedPipe = null;
  var pumpHouse = null;
  var supplyDepot = null;
  var time = 0;

  function createWaterTower(x, z, index) {
    var towerGroup = new THREE.Group();
    towerGroup.position.set(x, 0, z);

    // Tower leg - tall cylinder
    var legGeometry = new THREE.CylinderGeometry(0.8, 0.8, 20, 8);
    var legMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.7, roughness: 0.4 });
    var leg = new THREE.Mesh(legGeometry, legMaterial);
    leg.position.y = 10;
    leg.castShadow = true;
    towerGroup.add(leg);

    // Access ladder rungs - LineSegments
    var ladderGeometry = new THREE.BufferGeometry();
    var ladderPositions = [];
    var rungCount = 16;
    for (var i = 0; i < rungCount; i++) {
      var yPos = i * 1.25;
      // Left rung
      ladderPositions.push(-0.7, yPos, 0);
      ladderPositions.push(0.7, yPos, 0);
    }
    ladderGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(ladderPositions), 3));
    var ladderMaterial = new THREE.LineBasicMaterial({ color: 0xff6600, linewidth: 2 });
    var ladder = new THREE.LineSegments(ladderGeometry, ladderMaterial);
    ladder.position.y = 0.2;
    towerGroup.add(ladder);

    // Spherical tank at top
    var tankGeometry = new THREE.SphereGeometry(2.5, 16, 12);
    var tankMaterial = new THREE.MeshStandardMaterial({ color: 0x1a5f7a, metalness: 0.6, roughness: 0.3 });
    var tank = new THREE.Mesh(tankGeometry, tankMaterial);
    tank.position.y = 21.5;
    tank.scale.set(1, 0.7, 1);
    tank.castShadow = true;
    tank.receiveShadow = true;
    towerGroup.add(tank);

    // Sniper platform on tank - BoxGeometry
    var platformGeometry = new THREE.BoxGeometry(4, 0.4, 4);
    var platformMaterial = new THREE.MeshStandardMaterial({ color: 0x4a4a4a, metalness: 0.5 });
    var platform = new THREE.Mesh(platformGeometry, platformMaterial);
    platform.position.y = 24.5;
    platform.castShadow = true;
    towerGroup.add(platform);

    // Sandbag fortifications - stacked boxes
    var sandbagMaterial = new THREE.MeshStandardMaterial({ color: 0x8b7355, metalness: 0.1 });
    for (var sb = 0; sb < 3; sb++) {
      var sbGeometry = new THREE.BoxGeometry(0.6, 0.4, 0.6);
      var sandbag = new THREE.Mesh(sbGeometry, sandbagMaterial);
      sandbag.position.set((sb - 1) * 0.8, 25.2 + (sb * 0.35), 1.5);
      sandbag.castShadow = true;
      towerGroup.add(sandbag);
    }

    towers.push({ group: towerGroup, index: index });
    return towerGroup;
  }

  function createCatwalk(fromTower, toTower) {
    var walkGeometry = new THREE.BoxGeometry(0.6, 0.3, 8);
    var walkMaterial = new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.6 });
    var walkway = new THREE.Mesh(walkGeometry, walkMaterial);

    var fx = fromTower.position.x;
    var fz = fromTower.position.z;
    var tx = toTower.position.x;
    var tz = toTower.position.z;

    walkway.position.x = (fx + tx) / 2;
    walkway.position.z = (fz + tz) / 2;
    walkway.position.y = 22;

    var dx = tx - fx;
    var dz = tz - fz;
    walkway.rotation.y = Math.atan2(dx, dz);
    var len = Math.sqrt(dx * dx + dz * dz);
    walkway.scale.z = len / 8;

    walkway.castShadow = true;
    walkway.receiveShadow = true;

    // Railing LineSegments
    var railGeometry = new THREE.BufferGeometry();
    var railPoints = [];
    var railSegments = 10;
    for (var rs = 0; rs <= railSegments; rs++) {
      var t = rs / railSegments;
      var wx = fx + t * dx;
      var wz = fz + t * dz;
      // Vertical rail posts
      railPoints.push(wx, 22, wz);
      railPoints.push(wx, 23.5, wz);
    }
    railGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(railPoints), 3));
    var railMaterial = new THREE.LineBasicMaterial({ color: 0xff9900 });
    var railing = new THREE.LineSegments(railGeometry, railMaterial);

    catwalks.push(walkway);
    scene.add(walkway);
    scene.add(railing);
  }

  function createPumpHouse() {
    var phGeometry = new THREE.BoxGeometry(6, 4, 6);
    var phMaterial = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.4 });
    var house = new THREE.Mesh(phGeometry, phMaterial);
    house.position.set(-15, 2, -15);
    house.castShadow = true;
    house.receiveShadow = true;
    scene.add(house);

    // Roof vent - cylinder
    var ventGeometry = new THREE.CylinderGeometry(0.5, 0.5, 2, 8);
    var ventMaterial = new THREE.MeshStandardMaterial({ color: 0x999999 });
    var vent = new THREE.Mesh(ventGeometry, ventMaterial);
    vent.position.set(-15, 4.5, -15);
    vent.castShadow = true;
    scene.add(vent);

    pumpHouse = house;
    return house;
  }

  function createSupplyDepot() {
    var depotGroup = new THREE.Group();
    depotGroup.position.set(12, 0, -15);

    var crateSize = 1.2;
    var crateMaterial = new THREE.MeshStandardMaterial({ color: 0x8b6f47 });

    for (var cx = 0; cx < 3; cx++) {
      for (var cz = 0; cz < 3; cz++) {
        for (var cy = 0; cy < 2; cy++) {
          var crateGeometry = new THREE.BoxGeometry(crateSize, crateSize, crateSize);
          var crate = new THREE.Mesh(crateGeometry, crateMaterial);
          crate.position.set(cx * 1.3, cy * 1.3, cz * 1.3);
          crate.castShadow = true;
          depotGroup.add(crate);
        }
      }
    }

    scene.add(depotGroup);
    supplyDepot = depotGroup;
    return depotGroup;
  }

  function createFloodedWater() {
    var waterMaterial = new THREE.MeshStandardMaterial({
      color: 0x1a5f7a,
      metalness: 0.2,
      roughness: 0.6,
      transparent: true,
      opacity: 0.6
    });

    // Create water blocks in grid pattern
    for (var wx = -20; wx <= 20; wx += 4) {
      for (var wz = -20; wz <= 20; wz += 4) {
        var waterGeometry = new THREE.BoxGeometry(4, 0.5, 4);
        var water = new THREE.Mesh(waterGeometry, waterMaterial);
        water.position.set(wx, 0.25, wz);
        water.receiveShadow = true;
        waterBlocks.push({ mesh: water, baseX: wx, baseZ: wz });
        scene.add(water);
      }
    }
  }

  function createPipeSystem() {
    var pipePositions = [
      { from: [-5, 4], to: [5, 4] },
      { from: [5, 4], to: [5, 16] },
      { from: [5, 16], to: [-8, 16] },
      { from: [-8, 16], to: [-8, 4] }
    ];

    for (var pp = 0; pp < pipePositions.length; pp++) {
      var fromPos = pipePositions[pp].from;
      var toPos = pipePositions[pp].to;

      var dx = toPos[0] - fromPos[0];
      var dy = toPos[1] - fromPos[1];
      var dist = Math.sqrt(dx * dx + dy * dy);

      var pipeGeometry = new THREE.CylinderGeometry(0.25, 0.25, dist, 6);
      var pipeMaterial = new THREE.MeshStandardMaterial({ color: 0xaa0000, metalness: 0.8 });
      var pipe = new THREE.Mesh(pipeGeometry, pipeMaterial);

      pipe.position.x = (fromPos[0] + toPos[0]) / 2;
      pipe.position.y = (fromPos[1] + toPos[1]) / 2 + 0.2;
      pipe.position.z = 0;

      var angle = Math.atan2(dy, dx);
      pipe.rotation.z = angle - Math.PI / 2;

      pipe.castShadow = true;
      scene.add(pipe);
      pipes.push(pipe);

      // Control valve junction box
      var valveGeometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
      var valveMaterial = new THREE.MeshStandardMaterial({ color: 0xccaa00 });
      var valve = new THREE.Mesh(valveGeometry, valveMaterial);
      valve.position.set((fromPos[0] + toPos[0]) / 2, (fromPos[1] + toPos[1]) / 2 + 1, 0);
      valve.castShadow = true;
      scene.add(valve);
    }
  }

  function createBurstedPipe() {
    var sprayGeometry = new THREE.SphereGeometry(0.15, 4, 4);
    var sprayMaterial = new THREE.MeshStandardMaterial({ color: 0x4488ff, transparent: true, opacity: 0.7 });

    var sprayGroup = new THREE.Group();
    var sprayParticles = [];

    for (var sp = 0; sp < 8; sp++) {
      var spray = new THREE.Mesh(sprayGeometry, sprayMaterial);
      spray.position.set(5, 12, 0);
      spray.velocity = {
        x: (Math.random() - 0.5) * 4,
        y: Math.random() * 3 + 2,
        z: (Math.random() - 0.5) * 4
      };
      sprayGroup.add(spray);
      sprayParticles.push({ mesh: spray, velocity: spray.velocity });
    }

    scene.add(sprayGroup);
    burstedPipe = { group: sprayGroup, particles: sprayParticles };
  }

  function createPerimeterFence() {
    var fenceGeometry = new THREE.BufferGeometry();
    var fencePositions = [];
    var fenceRange = 35;
    var fenceSegments = 16;

    // Create fence perimeter
    for (var fs = 0; fs <= fenceSegments; fs++) {
      var angle = (fs / fenceSegments) * Math.PI * 2;
      var x = Math.cos(angle) * fenceRange;
      var z = Math.sin(angle) * fenceRange;

      // Vertical posts
      fencePositions.push(x, 0, z);
      fencePositions.push(x, 2, z);
    }

    // Horizontal rails
    for (var fr = 0; fr <= fenceSegments; fr++) {
      var angle1 = (fr / fenceSegments) * Math.PI * 2;
      var angle2 = ((fr + 1) / fenceSegments) * Math.PI * 2;

      var x1 = Math.cos(angle1) * fenceRange;
      var z1 = Math.sin(angle1) * fenceRange;
      var x2 = Math.cos(angle2) * fenceRange;
      var z2 = Math.sin(angle2) * fenceRange;

      fencePositions.push(x1, 1, z1);
      fencePositions.push(x2, 1, z2);
    }

    fenceGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(fencePositions), 3));
    var fenceMaterial = new THREE.LineBasicMaterial({ color: 0xcccccc, linewidth: 1 });
    fence = new THREE.LineSegments(fenceGeometry, fenceMaterial);
    scene.add(fence);
  }

  function init(sceneArg, cameraArg) {
    scene = sceneArg;
    camera = cameraArg;
    time = 0;

    // Lighting
    var ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    var directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(30, 40, 30);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    directionalLight.shadow.camera.far = 100;
    directionalLight.shadow.camera.left = -50;
    directionalLight.shadow.camera.right = 50;
    directionalLight.shadow.camera.top = 50;
    directionalLight.shadow.camera.bottom = -50;
    scene.add(directionalLight);

    // Create main water towers in a cluster
    var tower1 = createWaterTower(-10, -10, 0);
    scene.add(tower1);

    var tower2 = createWaterTower(10, -10, 1);
    scene.add(tower2);

    var tower3 = createWaterTower(10, 10, 2);
    scene.add(tower3);

    var tower4 = createWaterTower(-10, 10, 3);
    scene.add(tower4);

    // Connect towers with catwalks
    createCatwalk(tower1, tower2);
    createCatwalk(tower2, tower3);
    createCatwalk(tower3, tower4);
    createCatwalk(tower4, tower1);

    // Create infrastructure
    createPumpHouse();
    createSupplyDepot();
    createFloodedWater();
    createPipeSystem();
    createBurstedPipe();
    createPerimeterFence();

    // Ground plane
    var groundGeometry = new THREE.BoxGeometry(100, 0.2, 100);
    var groundMaterial = new THREE.MeshStandardMaterial({ color: 0x4a4a4a, metalness: 0.2 });
    var ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);
  }

  function update(delta) {
    time += delta;

    // Animate water waves
    for (var wbi = 0; wbi < waterBlocks.length; wbi++) {
      var wb = waterBlocks[wbi];
      var wave = Math.sin(time * 2 + wb.baseX * 0.1 + wb.baseZ * 0.1) * 0.15;
      wb.mesh.position.y = 0.25 + wave;
    }

    // Animate tower sway
    for (var ti = 0; ti < towers.length; ti++) {
      var tower = towers[ti];
      var sway = Math.sin(time * 0.5 + ti) * 0.05;
      tower.group.rotation.z = sway * 0.02;
    }

    // Animate bursted pipe spray
    if (burstedPipe) {
      for (var pti = 0; pti < burstedPipe.particles.length; pti++) {
        var particle = burstedPipe.particles[pti];
        particle.mesh.position.x += particle.velocity.x * delta;
        particle.mesh.position.y += particle.velocity.y * delta;
        particle.mesh.position.z += particle.velocity.z * delta;

        particle.velocity.y -= 9.8 * delta; // gravity

        // Reset spray
        if (particle.mesh.position.y < 0 || Math.abs(particle.mesh.position.x) > 30) {
          particle.mesh.position.set(5, 12, 0);
          particle.velocity.x = (Math.random() - 0.5) * 4;
          particle.velocity.y = Math.random() * 3 + 2;
          particle.velocity.z = (Math.random() - 0.5) * 4;
        }
      }
    }

    // Animate pump house slightly
    if (pumpHouse) {
      pumpHouse.rotation.y = Math.sin(time * 0.3) * 0.01;
    }

    // Pipe color pulse
    for (var pii = 0; pii < pipes.length; pii++) {
      var pressurePulse = 0.5 + Math.sin(time * 3 + pii) * 0.5;
      pipes[pii].material.emissiveIntensity = pressurePulse * 0.3;
    }
  }

  function reset() {
    time = 0;
    towers = [];
    catwalks = [];
    waterBlocks = [];
    pipes = [];
    fence = null;
    burstedPipe = null;
    pumpHouse = null;
    supplyDepot = null;

    if (scene) {
      var objectsToRemove = [];
      scene.traverse(function(child) {
        if (child !== scene && child.parent === scene) {
          objectsToRemove.push(child);
        }
      });

      for (var oi = 0; oi < objectsToRemove.length; oi++) {
        scene.remove(objectsToRemove[oi]);
      }
    }
  }

  return {
    init: init,
    update: update,
    reset: reset
  };
}());

;
} catch(_e){ if(window.console&&console.warn)console.warn("mod fail water-tower-siege.js",_e&&_e.message); }
