    addMesh(new THREE.CylinderGeometry(0.7, 0.7, 4, 12), truckMaterial, -8, 1, 12, 1, { z: Math.PI / 2 });
    addMesh(new THREE.BoxGeometry(0.5, 3, 3), forkMaterial, -10, 4, 10, 1, {});
