    fire.castShadow = true;
    fire.receiveShadow = true;
    fire.scale.y = 1.5;
    fire.position.set(-6, 0.5, 0);
    campGroup.add(fire);
    totalGeometryCount++;

    campGroup.userData.fireGlow = fire;
    animatedObjects.push(campGroup);
