    entrance.position.set(0, 4, -35);
    entrance.castShadow = true;
    entrance.receiveShadow = true;
    group.add(entrance);

    // Crypt opening
    var cryptGeom = new THREE.BoxGeometry(5, 10, 2);
    var cryptMat = createMaterial(COLORS.charred, 0x000000);
