    // Guard post structure
    var postGeom = new THREE.BoxGeometry(12, 6, 8);
    addMesh(postGeom, woodMat, -50, 3, 30);

    // Guard tower
    var towerGeom = new THREE.CylinderGeometry(3, 3.5, 8, 8);
