    var cabinGeo = new THREE.BoxGeometry(2.2, 1.8, 1.5);
    var cabinMat = new THREE.MeshStandardMaterial({
      color: colors.hazardGray,
      metalness: 0.5
    });
    var cabin = new THREE.Mesh(cabinGeo, cabinMat);
    cabin.position.set(x, y + 1, z + 3);
    scene.add(cabin);
