    shipObjects.push(mast1);

    var mast2Geo = new THREE.CylinderGeometry(0.8, 0.8, 18, 10);
    var mast2 = new THREE.Mesh(mast2Geo, materials.metalGray);
    mast2.position.set(-10, 5, -8);
