    var crackGeo2 = new THREE.BoxGeometry(1, 20, 15, 1, 4, 3);
    createObject(crackGeo2, crackedSectionMaterial, 29, 5, 15);

    var breachGeo = new THREE.BoxGeometry(8, 8, 1, 2, 2, 1);
