    createSeaFortressTowers();
    createNavalGunBattery();
    createHarborEntrance();
    createBoatDock();
    createBarracksBuilding();
    createSupplyTunnel();
    createCoastalArtillery();
    createTorpedoStorage();
    createWaveAction();
    createFlagTower();
    createSearchlight();
    createAdditionalStructures();

    return fortressObjects.length;
