  function createBlizzardParticles() {
    for (var i = 0; i < 60; i++) {
      var particleGeo = new THREE.SphereGeometry(0.15, 4, 4);
      var particle = new THREE.Mesh(particleGeo, materials.snowParticle);

      particle.position.set(
        (Math.random() - 0.5) * 80,
        (Math.random() * 30) + 5,
        (Math.random() - 0.5) * 80
      );

      particle.velocity = {
        x: (Math.random() - 0.5) * 3,
        y: -2 - Math.random() * 2,
        z: (Math.random() - 0.5) * 3
      };

      addObject(particle);
      blizzardParticles.push(particle);
    }
  }

